window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["30310710"]={"book":{"id":30310710,"title":"七堂思维成长课(精英群体的行为习惯)(精)","author":"(英)卡罗琳·韦布","translator":"熊舟","publisher":"中信","pubdate":"2018-08-01","isbn":"9787508689951","tags":["自我管理","思维","成长","心理学","心理学、思维、决策","管理","方法论","管理学"],"memCount":6},"np":1,"pb":[13],"idx":[{"i":18003,"t":"“积极的拒绝”+“设定边界的三个步骤”","l":"TF2-4","c":"大米","g":1,"p":1},{"i":10649,"t":"有效拒绝掌控自我","l":"TF2-2","c":"锐群","g":1,"p":1},{"i":10245,"t":"如何积极地拒绝别人","l":"TF2-1","c":"石榴","g":1,"p":1},{"i":9069,"t":"如何用积极的方法拒绝别人","l":"TF1-2","c":"王海英","g":1,"p":1},{"i":8584,"t":"学习如何制定计划和如何实现目标","l":"TF2-3","c":"王晓霞","g":1,"p":1},{"i":8406,"t":"制定计划和如何实现目标","l":"TF2-3","c":"王晓霞","g":1,"p":1},{"i":7882,"t":"沟通效率！","l":"TF1-2","c":"流觞","g":1,"p":1},{"i":7573,"t":"沟通效率","l":"TF1-2","c":"流觞","g":1,"p":1},{"i":7484,"t":"给大脑建立过滤机制","l":"TF2-4","c":"王晓霞","g":1,"p":1},{"i":7174,"t":"如何拒绝他人","l":"TF3-1","c":"王晓霞","g":1,"p":1},{"i":6644,"t":"如何通过建立大脑过滤机制帮助我们完成任务","l":"TF2-4","c":"王晓霞","g":1,"p":1},{"i":6620,"t":" 如何拒绝他人","l":"TF3-1","c":"王晓霞","g":1,"p":1},{"i":6419,"t":"《七堂思维成长课》TF2-4","l":"TF2-4","c":"王晓霞","g":1,"p":1}],"ms":[{"id":18003,"topic":"“积极的拒绝”+“设定边界的三个步骤”","learn_goal":"","remark":"个人都期待，可以把工作和生活安排的井井有条，成为别人眼中的成功典范。积极的拒绝\"和“设定自我边界的三个步骤”，都指向如何认识自己的需求和价值，通过保护个人空间与心理健康，从而更好的关照自己。希望我们掌握这样自我调节的工具，将自己建设的更好。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"大米","city":"郑州市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>常亚琳拆书2-4过级实录\u003c/p>\u003cp>书籍名：《七堂思维成长课》\u003c/p>\u003cp>作者：【英】 卡罗琳.韦布\u003c/p>\u003cp>主题：积极的拒绝&amp;设定自我边界的三个步骤\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>1分钟\u003c/p>\u003cp>各位亲爱的伙伴，大家好！我是大米，我的三个标签是：小学校长、RIA学习力导师，儿童阅读推广人。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>因为稍后会有一些需要合作学习的环节，因此我们在场的小伙伴进行一下分组，左右两边的小伙伴，各为一组。\u003c/p>\u003cp>\u003cstrong>【学习总目标】\u003c/strong>\u003c/p>\u003cp>大家在随我完成本次的RIA现场学习后，学习者能够现场应用“积极的拒绝”和“设定边界的三个步骤”两个工具，发现自己的内心需求，从而成功完成拒绝，设定好自己的边界。\u003c/p>\u003cp>\u003cstrong>【图书分享】\u003c/strong>2分（到这里用时共3分）\u003c/p>\u003cp>\u003cstrong>FAB法介绍\u003c/strong>\u003c/p>\u003cp>F：这本《七堂思维成长课》作者是卡罗琳.韦布，她是麦肯锡全球1%的女性合伙人，伦敦分公司董事。为世界知名公司及政府领导人提供过咨询服务。这本书用七个章节呈现了麦肯锡内部人士推行的7个行为。\u003c/p>\u003cp>A：这本书是领导和自我提升类的畅销书，被翻译为13种语言，畅销60余个国家。被《福布斯》杂志当年推荐为阅读商业书籍之一；被《财富》杂志推荐为很好的自我提升书籍之一；国内外近20位行业人士推荐。\u003c/p>\u003cp>B：你有没有过在沟通中出现分歧却又没有较好处理的经历？这本书教你如何结交和管理人脉；你有没有过面对焦虑，无助、愤怒和自我怀疑的负面情绪？这本书告诉你如何安排自己的生活，正确面对负面情绪，打造自己的高质量生活。\u003c/p>\u003cp>每个人都期待，可以把工作和生活安排的井井有条，成为别人眼中的成功典范。\u003c/p>\u003cp>今天，我给大家带来的是“积极的拒绝 ”和“设定自我边界的三个步骤”。他们两个是并列的关系，都指向如何认识自己的需求和价值，保护个人空间与心理健康，从而更好的关照自己。希望我们掌握这样自我调节的工具，将自己建设的更好。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>接下来，我们开始一起学习今天的第一个片段。\u003c/p>","ratings_count":3,"texts":[{"id":22249,"quote":"\u003cp>\u003cstrong>【学习目标1】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本环节的RIA现场学习后，能够现场运用积极拒绝的方法，在对方盛情邀约，自己又没法答应的情况下，成功拒绝对方。\u003c/p>\u003cp>请大家用1-2分钟的时间看手中的第一页片段内容，完成的小伙伴请抬头示意我。\u003c/p>\u003cp>\u003cstrong>主题1：积极的拒绝\u003c/strong>2分（到这里用时共5分）\u003c/p>\u003cp>R080-081\u003c/p>\u003cp>现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自画像这件事……”，听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进入了防守模式:“你要退出!出现威胁!”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003c/p>\u003cp>为了更多地与处于发现模式的人交流，提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如:\u003c/p>\u003cp>热情开场。首先认可并且赞许对方的请求。\u003c/p>\u003cp>你的“是”。然后，不要以“真的很抱歉……”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003c/p>\u003cp>你的“不”。解释清楚情况，表达遗憾之意，意思就是你无法答应他们的请求。\u003c/p>\u003cp>温情结尾。也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结束语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>\u003cp>(过渡语)好的，我看到小伙伴们都看完了拆页部分的内容，接下来我们一起来学习。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>4分（到这里用时共9分）\u003c/p>\u003cp>（问题/反例）上周，我在准备单位的工作总结，当天必须完成并提交。中午好友拿着她参加比赛的课题资料来找我，请求我帮她修改。面对她的请求，拒绝的话到嘴边也没说出口。拿出午休的一个小时帮她修改。下午因为午休时间占用和集中精力修改材料，导致下午工作效率极低，加班到深夜才完成了工作总结，而且还不是让自己太满意。\u003c/p>\u003cp>\u003cstrong>（通常做法）\u003c/strong>通常人们在面对他人请求时，总是难以拒绝，即使自己有着更重要的事情，也会不得不放下而优先完成他人的请求。\u003c/p>\u003cp>\u003cstrong>（不这么做的坏处）\u003c/strong>这样做不但会影响到自己工作的完成，影响到工作的绩效，长此以往甚至会被他人贴上“老好人”的标签，不但不会感激你，还会觉得理所当然，对个人的心理造成极大的影响。\u003c/p>\u003cp>\u003cstrong>【HOW】：（细化行动步骤）\u003c/strong>\u003c/p>\u003cp>如何做到“积极的拒绝”呢？有这样三个步骤\u003c/p>\u003cp>1、热情开场；\u003c/p>\u003cp>①认可并且赞许对方的请求；\u003c/p>\u003cp>②兴高采烈地表达正在忙的要紧事，解释为什么有意思、很重要或意义重大；\u003c/p>\u003cp>③（找一个能和你的谈话对象产生共鸣的理由）\u003c/p>\u003cp>2、解释情况，表达遗憾：为什么无法答应他们的请求；\u003c/p>\u003cp>3、温情结尾；\u003c/p>\u003cp>①在不影响自己的前提下，给出建议或提供帮助；\u003c/p>\u003cp>②热情祝愿对方项目成功；\u003c/p>\u003cp>\u003cstrong>（反例转正例）\u003c/strong>\u003c/p>\u003cp>如果回到当时，我会用“积极的拒绝”向闺蜜表达拒绝；\u003c/p>\u003cp>小静：“老常，帮我看看我的课题，急啊明天评审。”\u003c/p>\u003cp>我：“亲爱的，你太信任我了，感谢你在这么重要的事情上想到我并需要我，我对你这个课题非常感兴趣，他刚好是我最近研究的方向。”\u003cstrong>（热情开场：认可并赞许对方的请求）\u003c/strong>我：“但你也知道，年终岁尾，我今天手里压了一个学校总结，需要在今天下午下班前交到办公室。如果不能按时交，会影响到我们单位今年的年终整体考评。\u003cstrong>（热情开场：兴高采烈的表达正在忙的要紧事，解释为什么有意义）\u003c/strong>而且，把我们单位一年以来的工作客观良好的呈现，也是为了咱们单位的社会声誉与良好形象啊，为咱们单位年终评优做准备。\u003cstrong>（找一个能和你的谈话对象产生共鸣的理由）\u003c/strong>\u003c/p>\u003cp>我：但是，为了全力去写好这份总结，我也不得不放弃这两天想做的其他事情，很遗憾，其中就包括和你一起研究这个课题。这是我感兴趣的方向，所以也很失落。\u003cstrong>（解释情况，表达遗憾：为什么无法答应他们的请求；）”\u003c/strong>\u003c/p>\u003cp>我：不过我最近一直和教务主任在做这个研究，如果你需要，我可以联系她和你一起修改。\u003cstrong>（温情结尾；在不影响自己的前提下，给出建议或提供帮助；）\u003c/strong>\u003c/p>\u003cp>我：也祝你明天课题评审顺利通过哦！\u003cstrong>（热情祝愿对方项目成功；）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【Where】：\u003c/strong>\u003c/p>\u003cp>积极的拒绝适用于工作场合，当面对超出自己能力范围或职责范围的请求时、也适用于人际关系当中，当对方的请求或提议与你的价值观、原则或利益相冲突时。\u003c/p>\u003cp>不适用于当对方提出的请求非常紧急或重要，关乎生命安全、健康紧急状况或者其他重大事务时。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有些小伙伴可能会说，这不麻烦吗？直接拒绝说“不行”不就完了。很多时候，直接拒绝是很伤人的，有可能会伤害到彼此关系和感情。一个完美的拒绝既能让我们收获友谊，又能让我们化解自己的矛盾，是双赢的办法。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>亲爱的伙伴，为了更好的掌握刚学习的技能，接下来让我们一起来开启一场回顾反思与展望之旅。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1显象提问】\u003c/strong>3分（到这里用时共12分）\u003c/p>\u003cp>\u003cstrong>（激活经验）\u003c/strong>\u003c/p>\u003cp>请你回顾在近三个月中，有没有遇到过他人向你提出要求，但内心却并不想答应的情况？可能是和你不太利益相关的酒局？一次分享邀约，或者是想通过你的引荐去认识某人，或多久都不再联系的亲戚找你办事，毕业之后从未有过见面的同学的婚礼请柬……\u003c/p>\u003cp>想一想这件事情发生的时间，场景，结果。用1.5分钟时间按照刚才的分组和你小组内的伙伴进行交流。\u003c/p>\u003cp>（过渡语）\u003c/p>\u003cp>好的，接下来，我们请一位小伙伴来分享她们刚才的交流。请按照促学手册中第3页的建议，一句话概括即可。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>爱海老师：半个月之前，当时我正在参加便签营，一个北京来的朋友，中午\u003c/strong> \u003cstrong>11 点左右的时候，突然邀我晚上一块见面。说实在我特别想见他。我也挺喜欢他的，但是特别紧张。我可纠结，我只有把自己搞紧张。我就赶快在\u003c/strong> \u003cstrong>6 点之前，赶快把他便签写完以后，然后骑车路上骑的可快跑去和他见面。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>这位伙伴的场景，表述清晰而准确，让我们给到她掌声。\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>3分（到这里用时共15分）\u003c/p>\u003cp>\u003cstrong>（反思加工）\u003c/strong>\u003c/p>\u003cp>亲爱的伙伴，假如时光可以倒流，当学会了积极拒绝的三个步骤，再次回到刚才那个场景，面对同样的情况，你会怎样积极的拒绝呢？我们依然用2分钟的时间在小组内和伙伴进行交流。具体步骤请参照促学手册第3页，学习者分享二部分的建议步骤。\u003c/p>\u003cp>好的，交流时间到，我们邀请一个小伙伴和大家分享她们刚才的交流。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>爱海老师：听到你来来郑州了，特别开心，特别想见你，还带了几个孩子游学到我们郑州，大郑州还有很多好玩的。我最近哈在参加了一个学习变营，反正每天都要交作业，今天到现在作业还没交完。不打卡的话我毕业不了啊。我觉得你这个游学也很有意义，你在郑州待了好几天，是吧？那我们能那个改个时间，明天咱们再见面怎么样？我特别的羡慕你，带着孩子游学了一年啊。我也特别渴望和你交流，所以，相信你在郑州一定会带着他们收获很多。祝你们在郑州玩的开心。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>面对朋友的盛情邀约，爱海老师利用合理拒绝的三个步骤，做到了积极的拒绝，温情而美好，为他点赞！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":22250,"quote":"\u003cp>\u003cstrong>Part2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>1分（到这里用时共16分）\u003c/p>\u003cp>刚才我们谈到了“积极的拒绝”的方法，但是，不是每个要求都能积极的处理，况且“积极的拒绝”是要使用在有价值的且有较高利害关系的事件上。因此，我再给大家介绍一个方法，帮助你提前将这些要求拦截在烦恼之外，这就是设定自我边界的三个步骤，他能帮助我们保护个人空间与心理健康。这是一组并列关系的方法，都指向通过了解自己，认识自己的需求和价值，设定合理的边界与拒绝，实现更好的关照自己。接下来我们进入第二主题的学习——设定自我边界的三个步骤。\u003c/p>\u003cp>\u003cstrong>【学习目标2】\u003c/strong>在跟随我完成本环节的RIA学习之后，能够现场运用设定自我边界的三个步骤，发现自己的需求，设定自己的边界。\u003c/p>\u003cp>请大家用1-2分钟的时间看手中的片段内容，完成的小伙伴请抬头示意我。2分（到这里用时共18分）\u003c/p>\u003cp>\u003cstrong>主题2：设定自我边界的三个步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R083\u003c/strong>\u003c/p>\u003cp>有时候你会感觉其他人的要求从四面八方向你袭来。克里斯汀在职业生涯早期就经常碰到这样的情况。她是一位思维敏锐的人力资源总监，任职于一家全球性制药公司，有4个孩子，通勤时间长，工作又很繁忙。随着家庭成员不断增多，她一开始也感到保持工作和生活的平衡特别费力。\u003c/p>\u003cp>“我休完第三个产假回来工作后,”她回忆道(不自觉地用起了现在时态)，“感觉有4年都没怎么睡觉了。因为我休假期间没人替我干活,工作进度落下了3个月，而且我工作严重超负荷。我坐在办公室里，觉得特别生气，想要分辨清楚我到底对谁生气。一开始我冲着公司发火。我生气是因为他们总让我很早就过来开会，并且很晚才能走。但我转念一想，谁是‘公司’?”就在那一刻，她说,“我顿悟了，因为我意识到我主要是生自己的气，气我没有设定边界。我任由事态失控，然后还责怪别人。但如果我自己不设定边界，谁会给我设定边界呢?”她笑着摇摇头，“莫非还想着公司会说，‘噢，克里斯汀，你刚当妈妈，真不容易，8点前别工作，不要6点后再走?’不是的，这一切都由我来定。也许本不该如此，但确实就是这么回事。”\u003c/p>\u003cp>于是，克里斯汀决定把掌控权握在自己手里。“我在笔记本上写下我设定的边界:‘我不接受8点前开会。我6点后不会加班。中午12点到13点我要坐在桌子前，我要吃午饭。我到家就处理家事，工作时就工作。”这个清单很短。“即使这么做对职业生涯不利，也不管了，我想。我不能再这么继续下去了。讽刺的是，我执行了那个边界清单后，事业反而青云直上。”她想，为什么会如此呢?“因为那么做让我更沉着高效。另外，我当时不是高管，但我想这么做，说明我有能力担当高管，因为我知道如何管理自己。”\u003c/p>\u003cp>克里斯汀采取的一个做法就是，直接说明她什么时候有空，什么时候没有空，不会临时变动。“我使用非常清楚的语句，比如:‘我上午10点必须结束’。我这么说就够了。”她不自缚手脚，试图解释为什么她要准点离开会场。“而且无论如何，我到点就走。”\u003c/p>\u003cp>这种毫不含糊地厘清边界的方法非常有用，因为人的大脑会把模棱两可和不确定性视为威胁。与之相对，清晰明了的信息具有出乎意料的镇定作用，即使这些信息并不完全尽如人意。“我下定决心不能每天都对别人生气,”克里斯汀补充道，“我必须清楚我能做什么、不能做什么，并且我要愿意表达出来，然后说到做到。”此后，她一路获得升迁。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>8分（到这里用时共26分）\u003c/p>\u003cp>（过渡语）好的，我看到伙伴们都看完了这个拆页的内容，接下来我们一起来学习。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>今天我们谈论的边界，来自于心理学术语，他指的是“边界感”。\u003c/p>\u003cp>百度百科这么定义“边界感”：让你的事归你，我的事归我。包含物质边界、空间边界。\u003c/p>\u003cp>边界感在人际关系中扮演者重要的角色，不仅是自我保护的一种方式，也是对他人尊重的体现。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>边界感是人际关系中的一道防线，保护着我们的个人空间，避免不必要的冲突，促进健康的关系发展，帮助我们成为更加独立的个体。如果没有建立良好的边界感，经常将他人的需求和感受看得比自己更重要，你可能就会面对工作被动，人际关系紧张，人际冲突不断等问题，让你的生活一团糟。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>如何设定自我边界呢？有这样三个步骤：\u003c/p>\u003cp>1、设定界限（我不接受的）例如：不接受8点前开会\u003c/p>\u003cp>2、设定原则（必须做到的）例如：中午12点到13点我要坐在桌子前吃午饭\u003c/p>\u003cp>3、设定时间点：什么时候有空，什么时候没空。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（过渡语）为了更好的理解刚才拆页的内容，掌握方法步骤，我给大家分享一个我自己的案例。\u003c/strong>这是我和一个朋友在聊前几年工作状态时候的一段谈话记录，我的回忆：\u003c/p>\u003cp>“我做了副校长以后。感觉有一年时间都无法喘过气来。因为我负责了单位两个口的主管工作，但其中一个部门前任主管由于工作停滞已经落下了半年以上的进度，工作量大的难以想象。晚上我经常加班到深夜，看着还有那么多的清单，眼泪不争气的一直在往下流。家里俩孩子等妈妈，而我的加班没有休止符。我静静地坐着，仔细思考原因到底出在了哪里，我究竟为什么难过。一开始我认为是单位的分工，我难过是因为我的分工太多，导致有做不完的沟通，干不完的项目。但我深入思考，谁是‘分工’？”\u003c/p>\u003cp>就在那时，“我顿悟了，我难过的主要来源是我自己，我难过是因为我没有设定边界。分工和实操之间有很大的距离，但我没有控制好哪些是我的，哪些是他们的，还怪分工太多。所以，是需要审视自己的工作并设定一个边界的时候了！”我对我自己说，“你还等着领导说，’大米，你家里还有俩孩子，别太熬着，他们的工作让他们自己完成，你只需要点拨协调就行，设定时间点，按时上下班。’根本不可能，这是你自己的事情，谁会帮你做这些决定。”\u003c/p>\u003cp>于是，我决定调整工作方法，设置自己的边界。我在笔记本上列出我的边界：“早晨8点10之前不到岗，下午18:00前我结束一天的工作不接受加班（设定界限，我不做的），中午13点到14点我要午休，（设定原则——我必须做的）在家期间我不接受电话微信咨询讨论工作。”这个边界清单简短而清晰，“即使这么做会让我的这两个部门工作低效，或者她们说我不够履职尽责，我也不在意”。我就从那以后按照这个边界清单执行，但有趣的是，她们都提高了自己的工作效率，在我给出的工作时间内完成任务，也让我带动了这两个部门的高效运转。从那时起，我的工作也越做越好，因为我工作期间的高效和专注，而且关注于自己管理层面的项目和创新，很快，从副校长走到了正校长的岗位。\u003c/p>\u003cp>我还采取了非常明确的做法，就是我的时间和我关注的内容，我会直接在部门会议上说出来，我什么时间有空，什么时间没空，不会因为一些原因而发生临时变动，比如我会说“我今天下午17点之前必须结束这个项目。”（设定时间点：什么时候有空，什么时候没空。）而且我会严格执行，到了这个时间点我就结束这项工作。不解释原因，到时间就不再为这个项目投入时间，他们也不会再来找我。而且，到了这个点，我就开始执行下一个清单任务。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>1分（到这里用时共27分）\u003c/p>\u003cp>适用于定义个人空间与隐私、为自己做时间管理、进行职业规划与发展等场景中；不适用于需要紧急救援或救助、家庭的责任与义务、社交场合的礼仪、与道德法律约束冲突的场景中。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>5分（到这里用时共32分）\u003c/p>\u003cp>为了大家更好的掌握设定边界感，接下来我们来做一组练习。请大家看向促学手册P5。\u003c/p>\u003cp>请大家设想一下，在未来的1个月里，你可能会遭遇到生活和工作难以平衡场景。\u003c/p>\u003cp>可能是你的同事，不分时间的各种工作电话；可能是你的同事各种蹭车；也可能是要你代买早餐、代买咖啡......;各种琐碎杂乱的事项不但影响了你的工作，还影响了你的生活；\u003c/p>\u003cp>给大家30秒钟的时间，来想一想，你的脑海里首先出现的是什么情景？\u003c/p>\u003cp>构思好了吗？接下来，请在小组内用三分钟交流讨论一下我们想到的场景。要有具体的时间地点。稍后我会请一个小伙伴来分享。\u003c/p>\u003cp>（过渡语）：接下来，邀请一位小伙伴来分享下刚才再组内交流到的场景。请出倩倩小伙伴来分享。参照促学手册P5分享一的格式进行分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>倩倩：下个月我休工休假，我不想接任何电话，我不想接任何我同事的电话，但是他们可能会给我打电话，我是不想接电话。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家点评】\u003c/strong>\u003c/p>\u003cp>好的，倩倩刚才跟我们分享了一下，他下个月可能在歇工休假的时候，可能会迎来这个同事给他打关于工作电话的这种烦恼，是一个非常好的一个场景。\u003c/p>\u003cp>\u003cstrong>（分步催化2）\u003c/strong>5分（到这里用时共37分）\u003c/p>\u003cp>刚刚大家分享了未来可能遇到生活和工作难以平衡的场景。那接下来，请大家想一想，如果刚才我们设想的情景真的发生了，你如何运用“设定自我边界三个步骤”？请大家思考1分钟，按照刚才给出的三步的流程来帮助自己，然后写在你的P5促学单（二）分享二部分。\u003c/p>\u003cp>写的时间是2分钟。\u003c/p>\u003cp>我们请倩倩分享一下（分享时间2分钟）：\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>倩倩：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>休息日我不接电话，不要找我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>平时我正常的上班，我上班时间点，比如\u003c/strong> \u003cstrong>8 点半我上班， 5 点半下班，我正常了，我必须，我肯定是早上 8 点半去上班，晚上 5 点半下班，我这个时间我不会迟到，我也不会早退。然后当我休息日真的有什么事你们要找我的时候，请在就是 12 点到 1 点之间去找我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家点评】\u003c/strong>\u003c/p>\u003cp>倩倩刚才在分享中，三步流程这里边都用到了，我什么时间不能干什么？我什么时间可以干什么？我的具体的时间点。非常好！使用这个自我边界的三个步骤帮助我们解决问题，实现生活和工作的平衡。\u003c/p>\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>过渡语\u003c/strong>2分（到这里用时共39分）\u003c/p>\u003cp>刚才，我们尝试使用了“设定自我边界的三个步骤”，解决自己未来可能面临的问题，从而实现生活与工作平衡。\u003c/p>\u003cp>接下来，为了更好的掌握这个工具，我们再做一组练习。在这里，我给大家提供一个需要设置自我边界的场景，请大家边听边思考，如何帮助李明在工作中中通过设定自我边界，调试自己和同事之间的关系，做到保护自己，尊重他人。请打开促学手册P6.\u003c/p>\u003cp>\u003cstrong>（场景设计）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在一家科技公司工作的李明，经常面临在即将下班的时候项目组通知开会，这种情况让他很困扰；下班之后，经理经常会打电话来询问原本第二天才需要汇报的工作，导致他常常加班到很晚，工作无法按照计划执行，甚至弄的周末也时常被占据；隔壁部门老张经常在午饭时间过来交流项目进度，李明感到非常疲惫。他需要有自己的私人时间，除了工作，他还有家庭，还有生活。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（小组讨论）\u003c/strong>3分（到这里用时共42分）\u003c/p>\u003cp>接下来，给到大家3分钟的时间，请小组内运用拆页技巧“设定自我边界的三个步骤”讨论一下，帮助李明厘清自己的边界，维护健康和谐的人际关系，建立好边界感，形成李明的方案。具体可以参考使用P6促学单（三）环节1。\u003c/p>\u003cp>好的，我们请出小伙伴来分享下她们的解决方案。\u003c/p>\u003cp>\u003cstrong>【学员分享方案】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>爱海：第一个就是我不接受，就是不接受下班后谈工作。然后必须做到了，就是周末不工作，然后那个有时间没时间这一方面就是中午需要休息，没时间。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【评价】对，就是有时候我们去设定边境的时候可以再缓一些，再把我们的语言更加的这个柔软一些，这样的话设定出的边界会更容易被对方所接受。刚才爱海老师给大家说的其实已经很准确了，充分的表达出来了，我不接受什么，我必须做到什么，我设定的时间点是什么，我们可以再进一步的把语言温暖化、柔软化。好的，谢谢爱海老师。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（角色扮演）\u003c/strong>5分（到这里用时共47分）\u003c/p>\u003cp>有了方案，我们大致明晰了怎么帮助李明设定自己的边界了。接下来，再给到大家5分钟时间，小组内把这个方案改编成剧本演一演。具体可以使用我提供给大家促学单（三）环节2的微电影脚本设计框架。时间到了之后，邀请一个小组进行展示。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>好的，时间到，下面我们邀请一组伙伴来用角色扮演的方式展示方案。\u003c/p>\u003cp>\u003cstrong>【角色扮演小组展示】\u003c/strong>5分（到这里用时共52分）\u003c/p>\u003cp>\u003cstrong>项目组负责人：那个李明，你看都快\u003c/strong> \u003cstrong>5 点了，赶紧过来一趟，咱项目组开个短会吧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李明：噢，好，我马上过来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>项目组负责人：好，那个你先汇报一下我们这个项目的进度跟下一步的工作内容吧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李明：行，下一最近的进度进展了，非常的顺利，下一步的工作然后依然按照原计划进行，如果有特殊情况，我会及时向领导汇报。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>项目组负责人：好。（会议在晚上8点结束）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李明：领导，我能不能提一个意见？嗯，行，你说就是我们在开会的时候，因为我们这个项目一直进展的也很好，然后我们在开会的时候希望你把这个时间提前一下。我们 6 点下班，争取这个会议在 6 点之前结束，这样子也不耽误你回家的时间，也不耽误大家回家的时间，然后在平常的工作中，我们要求提高一下这个工作效率，我觉得这样做比较合适，您说呢？领导。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>项目组负责人：你这个提议很好，我们以后尽量早点开会，早点结束，大家早点下班。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>经理：李明在家干了，忙什么了？我刚想起来一个事，就是咱们明天还有一个汇报稿还没有写来，那个明天需要用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李明：领导你好，我是刚开完会到家，刚刚把这个包放下，你的电话就来了。然后这个具体明天的工作我已经安排得非常的清晰了，等到明天见面只需要\u003c/strong> \u003cstrong>5 分钟时间，我可以把它汇报清楚。明天 8: 50，我会之前我把这个工作思路给你汇报清楚，可以吗？领导。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>经理：为你点赞，工作做到前面了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>隔壁老张：吃过饭了没？咱这个项目进度我给你汇报一下来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李明：交流一下。紧张得很，你没看刚端着饭碗吗啊？交流项目可以，但是我觉得找一个更恰当的时间。嗯，是在吃饭时间，咱不谈工作，提高工作的这个幸福度。吃饭的幸福度你说行不行？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老张：嗯，行。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家点评】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好的，谢谢几位小伙伴。刚才分享的这个过程挺长的，然后每个人分享的角色，也扮演的惟妙惟肖的，大家设定好了自己的在这个过程中不接受几点开会，必须做到几点要干什么，然后并且确定好自己什么时间有空，什么时间是没空的。不要占用自己的这个下班时间，那么给大家的这种本色演出惟妙惟肖，给与掌声，谢谢。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>1分钟（到此处共用时 53分  ）\u003c/p>\u003cp>远而不疏是种能力，近而不入是种智慧。健康的“边界感”+“积极的拒绝”，助力你在工作和生活中表现的更好！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1724720801000,"updated_at":1729575979000,"ria":true},{"id":10649,"topic":"有效拒绝掌控自我","learn_goal":"","remark":"如何处理他人请求的沟通方法，它既能让我们保持良好关系建立持续的影响，还能通过拒绝一些非必要的请求来减少自我委屈自我牺牲，提高自己手上紧要事项的效率。”","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"锐群","city":"三亚市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp> 晚上好，各位！\u003c/p>\u003cp> 我是锐群，我是一名拆书家，也是今晚的拆书分享者。今晚我们要在这里一起拆书学习，相互促进，把知识拆为自己的能力。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp> 在我们正式分享开始之前，为方便下面的交流学习，先给大家组个队分个组。\u003c/p>\u003cp> 咱们依现场情况，我左手边的伙伴分为一组，右边的伙伴分为另外一组。\u003c/p>\u003cp> 接下来，请大家把目标投向我手中这本书，这本书叫《七堂思维成长课》\u003c/p>\u003cp>【FAB】\u003cbr>F\u003cbr> 本书作者卡罗琳·韦布，TA在世界级领先的全球管理咨询公司——麦肯锡任职，有12年的工作经验，《七堂思维成长课》主要讲了目标课、效率课、社交课、沟通课等七个来自精英群体行为习惯的主题内容；\u003cbr>\u003cbr>A\u003cbr> 书中的方法和建议都有来自心理、行为或神经科学方面最近几十年的科学理论和实证支持，在开篇部分就做了重点说明。相比同类书籍，它是少有的内容严谨又安排巧妙的一本书，让读者仅学习开篇不到全书1/10篇幅的科学理论和三大主题内容，就足以解决生活和工作中的大部分问题，可以减少读者拿到一本书就必须看完的焦虑。\u003cbr>\u003cbr>B1\u003cbr> 本书内容因为建立在科学理论和实证之上，可以从科学的角度帮助我们解决设定了目标又无法坚持和达成的问题，每天总有忙不完的要紧事焦头烂额又缺乏效率的问题，面对选择下决定时患得患失犹豫不决导致拖延和焦虑的问题，以及与人沟通时直言不讳容易伤人拐弯抹角又传达不了等问题。\u003cbr>\u003cbr>B2\u003cbr> 我们今天要一起探讨的片段是一个处理他人请求的沟通方法，它既能让我们保持良好关系建立持续的影响，还能通过拒绝一些非必要的请求来减少自我委屈自我牺牲，提高自己手上紧要事项的效率。\u003c/p>","ratings_count":1,"texts":[{"id":14515,"quote":"\u003cp>\u003cbr>R【原文片段】《七堂思维成长课》p80-81\u003cbr>\u003cbr> 现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自画像这件事……”，听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进入了防守模式：“你要退出！出现威胁！”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003cbr>\u003cbr> 为了更多地与处于发现模式的人交流，提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如:\u003cbr>\u003c/p>\u003cp> 热情开场：首先认可并且赞许对方的请求。\u003cbr> 你的“是”：然后，不要以“真的很抱歉…”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003cbr> 你的“不”：解释清楚情况，表达遗憾之意，意思就是你无法答应他们的请求。\u003cbr> 温情结尾：也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结束语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp> 今天这个片段的内容，讲了普通的、直接拒绝请求的方式可能引发的反应，抛出一个叫做“积极拒绝”的方法。它是一种融入了脑神经科学原理的沟通技巧，是一个在他人提出请求时，不伤感情不委屈自己的拒绝法。\u003cbr>\u003cbr>【how】它的具体步骤是：\u003cbr>1.认可请求（表认可）\u003cbr>首先认可并赞许对方的请求；\u003c/p>\u003cp>\u003cbr>2.解释要事意义（讲意义）\u003cbr>说明自已正在忙的要紧事，解释它为什么有意思、很重要（能和谈话对象产生共鸣的理由更佳）；\u003c/p>\u003cp>\u003cbr>3.表达拒绝（表拒绝）\u003cbr>解释情况，明确表达无法答应他们的请求；\u003c/p>\u003cp>\u003cbr>4.给予帮助或祝愿（送温暖）\u003cbr>在不影响自己完成真正优先事项前提下，提供力所能及的帮助或建议，如果不能，至少表达真心的祝愿，结束对话。\u003cbr>\u003cbr>【why】\u003c/p>\u003cp> 原文片段中提到两个词“防守模式”和“发现模式”，简单做个解释。“防守模式”指的是我们的大脑识别到对自己不利的信号时，本能表现出来反击或逃避或暂停推进行动的一种自我保护状态；“发现模式”是，当我们受到赞扬、鼓励、认可等有利刺激，激发出来的期待、探索等开放性的精神状态。\u003c/p>\u003cp>\u003cbr> 这两种模式，是近几十年来，神经科学和行为科学研究发现的，大脑为了保证种族繁衍，所进化和保留下来的一种内在机制和生存本能。\u003c/p>\u003cp>\u003cbr>（不这么做的坏处）我们通常拒绝请求时，往往是直接说“不”，或者是先陈述自己的要紧事，这些信号刺激就启动了对方的“防守模式”，轻则让对方失落让自己事后内疚，重则影响关系导致对方敬而远之。\u003cbr>（这么做的好处）而使用“积极拒绝”时，通过认可对方的请求、解释自己要紧事的意义产生共鸣等这些积极的信号，打开TA的“发现模式”，对方更具开放性的接受我们的理由，既不伤感情还使得对方期待下一次的请求。这就提高了拒绝成功率，让我们不再被动的委屈自己和牺牲时间而失去自我的掌控感。\u003cbr>\u003c/p>\u003cp>【例子】\u003c/p>\u003cp> 今年国庆和中秋叠加在一起，难得的假期。小长假前几天，长辈们计划着全家大小18口人一起回一趟老家。我因为国庆期间还有工作又考虑到疫情，都以直接拒绝又陈述理由的方式回应，结果导致了家里人反复的劝说。设想，当时使用“积极拒绝”的方式，是可以让大家更容易接受，也能更好的传达我的心意。\u003cbr>具体怎么表达拒绝呢？\u003cbr>（表认可）一个大家庭一起回老家过中秋，好提议，光想着就很兴奋。\u003cbr>（讲意义）同样很重要又振奋事情，是什么呢？我正在筹划最近的节日活动和实施客户拜访计划，这些安排会让我的工作更好进入正轨，这样一来，今年剩下的日子就不会那么吃力了，这个关键时期，为未来的几个月做一些充分准备，可以避免来年像今年一样难。\u003cbr>（表拒绝）这意味着，我不得不做些牺牲，再辛苦一点，其中也包括小长假我不能陪大家一起回去，好可惜。\u003cbr>（送温暖）当然，我留在家，这里临时有什么需要处理的，我也能安排上，孩子们难得出一次远门，会很期待，回来后一定有很多值得分享的经历，最重要的是一路安全平安、旅途愉快。\u003cbr>\u003cbr>【预防异议】\u003cbr> 那么，有没有可能，我们拒绝之后，对方又再次发出请求呢？要怎么办？\u003c/p>\u003cp>\u003cbr> 这里我们可能需要思考，是我们对要事重要意义解释得不够清楚还是没产生足够共鸣？是否只需要我们提供建议和帮助就足以解决这个请求呢？\u003cbr> 这个时候，我们可以在感谢对方盛情邀请和强烈请求之后，再次重复“积极拒绝”的步骤，但要把重点放在讲意义和送温暖这两个环节上。\u003cbr>\u003cbr> 另外再补充，如果是要拒绝一些小请求，是不是也要完整走完4个步骤呢？操作起来是不是小题大做？\u003cbr> 一些顺路帮忙取东西买东西，顺手帮忙，力所能及又不影响自己真正优先事项的前提下，我们当然可以做到举手之劳，而自己手头正忙，紧急得不能过多回复的情况下，通常只要简单强调我们的要紧事和提供建议帮助或表达祝愿，对方就能明白了。\u003cbr>　　\u003cbr>【适用边界】总结：\u003cbr> 使用“积极拒绝”这个方法的有效前提是，我们确有需要忙的要紧事而不是只有逻辑上、感性上的理由。它更适用在具有充分时间进行表达的对话场景，是提高拒绝的成功率，不伤感情不破坏关系不牺牲不委屈，又能主动掌控自我安排的一种有效拒绝请求的方法。\u003c/p>","interaction":"\u003cp>【分布催化1】：\u003c/p>\u003cp>拆书家提问：\u003cbr> 接下来，请各位关注你们自己，问一问自己：\u003cbr> 你在接下来的一周里，手上会忙哪些要紧的事情呢？\u003cbr> 是孩子的学习年末的备考？还是参加培训学习自我成长？或是工作上的，年底冲KPI做业绩、年底总结和下年度规划呢？\u003c/p>\u003cp>学习者1：工作上的，要做业绩。\u003c/p>\u003cp>学习者2：孩子的学习和工作上任务都有。\u003c/p>\u003cp>【分布催化2】\u003c/p>\u003cp>拆书家提问：\u003cbr>\u003c/p>\u003cp> 在你接下来一周里，亲友向你提出请求或是同事请求帮忙，而你手上正需要处理的你刚才所说的重要事项，你会怎么运用今天的“积极拒绝”来对话？请简单描述你的场景，加工出具体的语言。\u003cbr> 大家用3分钟在小组内讨论，讨论完成的请举手示意我，我们现场邀请1-2位伙伴来做分享。\u003c/p>\u003cp>学习者（钟泽）：\u003c/p>\u003cp> 这几周的晚上，朋友都时不时的会约我喝酒，而我近期需要把精力投入到孩子的学习上。在下周，有朋友再约我喝酒，我又必须陪孩子学习，我可以运用今天的“积极拒绝4步骤”这么表达：\u003c/p>\u003cp> 1.（表认可）\u003c/p>\u003cp> 工作了一天，约三五好友一起喝酒放松，这活动好吸引人，特别棒！\u003c/p>\u003cp> 2.（讲意义）\u003c/p>\u003cp> 你大概知道，我家孩子最近要考试，之前我都忙生意，没顾及到，这个学期是一个重要转折点，孩子学习是作为父母基本责任之一，处理好了我以后也可以少操心，能有更多时间陪兄弟们一起喝酒。\u003c/p>\u003cp> 3.（表拒绝）\u003c/p>\u003cp> 我今晚要准时回去陪孩子复习、布置任务和讲解，实在不能陪兄弟们聚了。\u003c/p>\u003cp> 4.（送温暖）\u003c/p>\u003cp> 大家喝得开心点，下次我请回各位。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1605710199000,"updated_at":1606788633000,"ria":true},{"id":10245,"topic":"如何积极地拒绝别人","learn_goal":"","remark":"你会拒绝别人吗？你知道积极拒绝的好处吗？你知道如何积极地拒绝别人吗？一起来学习精英群体的方法吧！","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"石榴","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>【自我介绍】大家好，我是刘芳。首先用三个标签介绍自己，第一个标签是17岁女孩的妈妈。第二个标签是感觉统合训练测评师，第三个标签是心理学爱好者。我今天的分享大概18分钟左右，首先感谢大家的聆听。\u003c/p>\u003cp>【F】今天的拆页来自《七堂思维成长课》，豆瓣评分8.2分，作者是卡洛琳·韦布，是管理咨询师，执行教练，她是麦肯锡全球1%的女性资深合伙人。\u003c/p>\u003cp>【A】跟一般自我成长的书不同，这本书的理论基础就有三门学科，分别是心理学、行为经济学和脑神经科学，作者把科学研究、实用建议和真实案例完美结合在了一起，读起来一点也不枯燥。\u003c/p>\u003cp>【B1】制定了计划，很多时候却完不成？这本书教你用特定词语，计划达成率提高15%；与客户或同事深度交流有困扰，这本书教你如何处理沟通中的分歧；面对焦虑、无助、自我怀疑等负面情绪，这本书有科学而实用的方法；我们还能从这本书学到很多，比如打造自我专业形象、提升行业影响力等等。\u003c/p>\u003cp>【B2】平时生活中，我们拒绝别人的时候，如果对方能够理解你，平静地接受你的理由，这也是一种能力，对不对？一起来学习这种能力吧！那我们先花2分钟时间阅读下面的拆页，看完了的小伙伴请向我示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":14083,"quote":"\u003cp>现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自画像这件事……”，听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进入了防守模式：“你要退出！出现威胁！”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003c/p>\u003cp>为了更多地与处于发现模式的人交流，提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如：【拆页中的HOW】\u003c/p>\u003cp>热情开场。首先认可并且赞许对方的请求。\u003c/p>\u003cp>你的“是”。然后，不要以“真的很抱歉……”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003c/p>\u003cp>你的“不”。解释清楚情况，表达遗憾之意，意思就是你无法答应他们的请求。 \u003c/p>\u003cp>温情结尾。也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结束语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>","explains":"\u003cp>好，我看大部分小伙伴都看完了，没看完也没关系，来听我讲。\u003c/p>\u003cp>【\u003cstrong>学习目标\u003c/strong>】希望通过今天的现场学习，大家能够学会如何用四个步骤积极地拒绝别人的请求。\u003c/p>\u003cp>下面我会结合实例详细讲解。\u003c/p>\u003cp>【\u003cstrong>人们常规的做法\u003c/strong>】对于别人的请求，如果我们不愿意答应，要拒绝的话，一般来说，我们会用“对不起”、“很抱歉”、“不好意思”等等否定的词语开头，是吧？然后说明自己不能接受的原因。\u003c/p>\u003cp>【\u003cstrong>这样做的坏处\u003c/strong>】用这些否定词语拒绝，对方大脑的第一反应就是受到了威胁，马上就进入了防守状态，这是一种本能的反应，就像发现房子着火要逃出去一样。当人进入防守状态时，他基本是没有思考能力的。而我们虽然拒绝对方，肯定还想得到他的理解，不想得罪他，是吧？所谓“买卖不成，仁义在”，以后还是要互相支持，对吧？然而，对于防守状态下的大脑，并没有思考能力，想让对方不带情绪地完全理解我们，就很难了。\u003c/p>\u003cp>【\u003cstrong>举负面例子佐证\u003c/strong>】举个我自己的例子，前段时间，我在上一个心理学网课。一共是三周的网课学习，我一开始申请了社群运营的整理任务。可能因为我们那个群都是老学员免费复训的，组长也没有认真组织，群里面的学习氛围一点都不热烈。一周过去了，营长就跟我私聊，想换我做组长。我一听就很为难，具体原因这里我就不详细说了。我当时就说“不好意思”，以时间有限、能力不够为理由拒绝了营长。说实话，因为今年还有三次21天的课程，我一点都不想得罪她。近段时间，第二阶段的课程又开始了，我申请复训的时候，营长就以资格不够为理由没有通过。\u003c/p>\u003cp>【\u003cstrong>拆页行动建议\u003c/strong>】后来看了这个片段，我就懊恼呀，如果我当时能用拆页中的方式拒绝她就好了，我后面的复训申请就能通过了。我把片段中的四个步骤提炼了一下。第一步，认可对方，认可对方的请求；第二步，说明理由，把自己拒绝的理由说清楚，最好是双方都认同的理由；第三步，表达遗憾，明确说明自己不能答应请求；第四步，祝福对方，给建议或是推荐其他人选，实在没有的话，也要简单祝福对方。第一步是认可对方，对方心情愉悦了，我们后面拒绝的理由，他不知不觉就接受了。\u003c/p>\u003cp>【\u003cstrong>将负面例子加工成正面例子\u003c/strong>】现在想来，根据拆页中四个步骤，我当时可以跟营长这么说：“这次幸福家的网课内容很好，很感谢您给我的复训机会。首先谢谢您肯定我的能力，您也知道，我要完成的事情很多，平时很忙，运营组织能力还很欠缺，现在实在没有时间边学边做，很遗憾不能接受组长的工作，要不您请群里的学习官来做组长，以后再开营的话，如果我时间能安排好，我还是愿意尝试的。”这段话里面，就包含了认可对方-说明理由-表达遗憾-祝福对方四个步骤。如果当时这么说，我就不会担心下次没有复训的机会了。\u003c/p>\u003cp>【\u003cstrong>适用边界\u003c/strong>】要注意的是，积极地拒绝虽然很好用，不容易得罪人，但是我们在拒绝之前，还是要权衡一下，有些情况，比如领导给你安排工作，比如团队成员分派任务等等，这些情况下，你如果经常拒绝，就算没有得罪对方，也失去了很多自我成长的机会，对吧？\u003c/p>","interaction":"\u003cp>下面我们要在小组内讨论，我们先来分组。从我左手边开始，两两一组。\u003c/p>\u003cp>【A1\u003cstrong>显像提问\u003c/strong>】那大家在平时的工作或生活中，应该都有过想要拒绝他人的情况。比如工作中某同事让你替他加班；或者让你做本该属于其他部门的任务；又比如某个交情一般的朋友，让你去机场接他；或者亲戚朋友给你介绍对象；还比如朋友聚餐或其他活动的邀请，或者朋友提出的参加某个投资理财的邀请；那现在请大家回想一下，有没有类似的情况，然后按拆页上标注的A1部分的提示写下来，写关键词就行了。1分钟时间。等下我会邀请小伙伴来分享一下。\u003c/p>\u003cp>请注意，因为时间关系，分享的时候不需要说自己拒绝的详细原因，只要说明当时您是怎么拒绝的就好了。\u003c/p>\u003cp>【小伙伴分享】\u003c/p>\u003cp>\u003cstrong>\u003cem>周月年案例：\u003c/em>\u003c/strong>就今天上午的事情，我的上一任领导拉了一个微信群，在里面说***的妈妈走了，让我们下午一起去参加追悼会。我当时比较着急，就直接回了一句，我们下午有纪念表彰会，不能参加。后面我就忙自己的事情了，现在听了老师的分享，回想起来，觉得自己拒绝得太直接了。\u003c/p>\u003cp>\u003cstrong>\u003cem>潇潇案例：\u003c/em>\u003c/strong>前段时间，我的阿姨要给我介绍对象，我就直接拒绝说暂时不需要。\u003c/p>\u003cp>【A1+反思加工】刚刚大家都回想了各自遇到的情况，现在假设我们有了一个回到过去的机会，在您刚才想到的场景中，用上我们学到的四步骤，思考一下，你会怎么积极地拒绝。可以在小组内讨论，也可以自己写下来以后在小组内分享。时间4分钟。请大家用关键词写下来，等下我会邀请一位小伙伴来分享。\u003c/p>\u003cp>我说清楚了吗？\u003c/p>\u003cp>我刚才在每个组都旁听了一下，大家都积极参与了。我们现在请一位小伙伴花2分钟时间分享一下。\u003c/p>\u003cp>\u003cstrong>\u003cem>潇潇案例：\u003c/em>\u003c/strong>\u003c/p>\u003cp>根据今天学习的内容，我可以这么说：（认可对方）阿姨，感谢你一直关心我个人的生活，一直帮我留意合适的人。（说明理由）我现在工作量比较饱和，工作之余也想进行学习，暂时没有太多的时间。（表达遗憾）这个人其实挺优秀的，但是我现在确实有自己的目标和事情，希望以后有机会有其他合适的可以进行接触。（祝福对方）还是再次感谢阿姨，以后确实有合适的还是要请阿姨帮我留意一下。\u003c/p>\u003cp>【结束】\u003c/p>\u003cp>好，今天我分享了如何积极地拒绝，四个步骤分别是认可对方、说明理由、表达遗憾、祝福对方，我们还进行了实操练习，希望大家把这个方法应用到生活中，我今天的分享就到此结束，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1596960890000,"updated_at":1599972770000,"ria":true},{"id":9069,"topic":"如何用积极的方法拒绝别人","learn_goal":"学会用积极的方式拒绝不合理的请求","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"王海英","city":"绍兴"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>介绍自己和书籍\u003c/p>\u003cp>各位爱学习爱生活的伙伴们，大家晚上好，欢迎参加拆书帮绍兴阳明筹备分舵的线下拆书活动。我叫王海英，我用三个标签介绍一下自己。1.新手拆书家2.演讲初学者3.素食主义者。\u003c/p>\u003cp>今天我的拆页来源于《七堂思维成长课》，作者是卡洛琳·韦布。她是麦肯锡公司全球1%的女性合伙人，伦敦分公司董事。作为一名管理咨询师，执行教练，她为世界知名公司及政府领导者提供过咨询服务。多年来她在职场中观察到:一个人生活质量的高低并不取决于他职位的高低，收入的多寡，而是思维的差异，今天我们通过这本书的其中一个片段来一探究竟。\u003c/p>\u003cp>【1-2技能点：给学习者分组】\u003c/p>\u003cp>为了让大家有更好的学习效果，我们后面会有个分享的环节，大家先做个简单的分组。右边的三位伙伴一组，左边的四位就俩俩一组。&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12816,"quote":"\u003cp>现在正式进入RIA学习环节，首先是［R 环节］，阅读原文\u003c/p>\u003cp>今天我的拆页主题是如何用积极的方式拒绝别人\u003c/p>\u003cp>拆页来源:《七堂思维成长课》P80-81\u003c/p>\u003cp>请大家花1分半钟的时间阅读一下原文拆页。阅读好的伙伴请给我个示意。\u003c/p>\u003cp>【1-2技能点：选书和选拆页】\u003c/p>\u003cp>什么是积极的拒绝\u003c/p>\u003cp>现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自画像这件事…”，听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进入了防守模式:“你要退出!出现威胁!”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003c/p>\u003cp>为了更多地与处于发现模式的人交流，提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如:\u003cbr>\u003c/p>\u003cp>1.热情开场。首先认可并且赞许对方的请求。\u003c/p>\u003cp>&nbsp;2.你的“是＂。然后，不要以“真的很抱歉…”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003c/p>\u003cp>3.你的“不”。解释清楚情况，表达遗憾之意，意思就是你无法答应他们的请求。\u003c/p>\u003cp>4.温情结尾。也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结東语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>","explains":"\u003cp>【1-2技能点:拆书家讲解引导】\u003cbr>\u003c/p>\u003cp>大家原文差不多阅读好了，接下来进入I环节，重述原文，没有阅读好的伙伴可以一起听我做一个解读。\u003c/p>\u003cp>【WHAT】文中主要介绍了一种新的拒绝方式，就是我们可以用积极的语言和态度去拒绝在工作和生活中碰到一些不合理的请求，而不是直接说“no”。\u003c/p>\u003cp>碰到不合理的请求我们为什么不直接拒绝呢？\u003c/p>\u003cp>【WHY】 &nbsp;平时我们碰到无法应承的请求时，往往是直接拒绝，这样做的结果通常会让对方产生抗拒心理，影响对方情绪，甚至影响双方的关系；但是勉强答应，为难的又是自己。如果我们换成正向的，对方能接受的方式来代替直接拒绝，不但能获得对方的理解，说不定还能加深双方的关系。\u003c/p>\u003cp>【HOW】如何用积极的方式拒绝对方\u003c/p>\u003cp>1.认同对方——先对对方的请求表示认同。\u003c/p>\u003cp>2.阐述事实——表示自己内心很想答应但是现实却不允许。\u003c/p>\u003cp>3.表达遗憾——对于无法应允对方请求，表达遗憾之情。\u003c/p>\u003cp>4.祝福对方——希望对方的问题能尽快得到解决或者帮忙提供其他的解决方案。\u003c/p>\u003cp>【WHERE】积极的拒绝这个方法不但适合职场人士使用，也适用于日常生活中的沟通交流 ，既维护了自己的意愿又保全了人际关系。\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>接下来我讲个自己的小故事介绍一下如何积极的拒绝。\u003c/p>\u003cp>这个月10号，我的朋友杨女士邀请我参加一场关于财商的公益沙龙。去听了之后，原来是邀请大家一起来做某个生态产业项目。我没有任何想法，但我又挺看重跟她的关系，不好一口回绝。我就借鉴了这个积极的拒绝方法跟她做了沟通。\u003c/p>\u003cp>1.认同对方——我说，谢谢你介绍这么多积极向上的朋友给我认识，还有这么好，有前景的项目。\u003c/p>\u003cp>2.阐述事实——因为最近在忙着学习，希望自己有所突破，也给自己定了一些目标，所以暂时没有精力去忙其他的事情。不过你们提到的国学班，我想有机会的话可以带孩子去体验一下。\u003c/p>\u003cp>3.表达遗憾——等我学习告一段落，有机会可以再进行一些交流，但目前非常遗憾不能参加这个项目。\u003c/p>\u003cp>4.祝福对方——这个项目由这么有经验的老师在牵头，前景肯定很不错，相信你在这里肯定会有很好的收获。\u003c/p>\u003cp>那我朋友听了之后表示能够理解。\u003c/p>","interaction":"\u003cp>［A1 激活经验］\u003c/p>\u003cp>【1-2技能点: 激活学习者经验】\u003c/p>\u003cp>讲完了我的案例，现在我们进入A1环节，激活经验。请伙伴们回忆一下，在过去的一周或者一个月内，你有没有碰到过，身边有人向你提出请求，你直接拒绝的情形？比如拒绝加班的要求；拒绝合作的建议；拒绝聚餐的邀约，请伙伴们花2分钟时间在各自小组内分享一下。\u003c/p>\u003cp>看到大家分享的差不多了，我们请一位伙伴给大家分享一下他的案例。请把你故事的主要场景给大家描述一下，包括时间，地点，人物，起因，经过，结果。\u003c/p>\u003cp>【学习者分享案例】\u003c/p>\u003cp>伟伟：昨天，一名销售人员又发来不属于我们单证部门工作范围的工作要求:合同制作和形式发票制作。因上周和上上周一时心软帮忙代做，反而给自己带来了负担，虽然婉转的表达过最好销售人员自行制作，但一直没有明确的进行拒绝。所以昨天又发过来，我当场直接拒绝，我不能给你做你们部门自己分内的事。当时就弄得双方都很尴尬。\u003c/p>\u003cp>谢谢这位伙伴的分享。\u003c/p>\u003cp>【A2 催化应用】\u003c/p>\u003cp>【1-2技能点:催化学习者应用】\u003c/p>\u003cp>接下来是A2环节，催化应用。请伙伴们用简洁的语言规划一下，未来一个月内，如果再次遇到上面类似的场景，你怎么用今天学的积极的方式去拒绝对方？请把时间，具体的目标，行动步骤写在便签上。\u003c/p>\u003cp>［学习者分享案例］\u003c/p>\u003cp>伟伟：\u003c/p>\u003cp>目标：未来一周内，销售部门再把他们的工作推给我们来做，就用今天学到的积极的拒绝方式拒绝对方这种推诿。\u003c/p>\u003cp>具体步骤：\u003c/p>\u003cp>1.认同对方－我知道你们部门生意好，最近工作比较多，都赶着出货，又加上有几位是新手，你可能是担心会出错。\u003c/p>\u003cp>2.阐述事实－你看销售部门工作忙起来，我们单证部门活也多了呀，柜子都等着呢。\u003c/p>\u003cp>3.表达遗憾－我手头上现在还有很多事要处理，这个工作真的顾不过来了。\u003c/p>\u003cp>4.祝福对方－让你们新来的同事去做没事的，相信他们一定能独当一面的。\u003c/p>\u003cp>因为时间的关系，今天我的分享就到此结束，希望伙伴们能把积极的拒绝这个方法用起来，去收获更多的美好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":12817,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":12818,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1571204897000,"updated_at":1571236876000,"ria":true},{"id":8584,"topic":"学习如何制定计划和如何实现目标","learn_goal":"制定目标扩大影响力","remark":"经营人群的行为和动作标准，如何制定目标如何扩大影响力，如何提高执行力。","level":"TF2-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>【学习目标一】\r\n希望大家在学习完这个内容之后，当你再遇到重要事情的时候，不再是被事情推着走，而是可以使用给大脑建立过滤机制的方法，帮助自己设计出一个顺利完成任务的计划。&nbsp;\u003c/p>\u003cp>【学习目标二】希望大家在学习完这个内容之后，希望你下次在设置目标的时候，能够预想到目标实现过程中可能出现的困难，并且把问题写下来再用，用“如果...那么...”的方法寻找到解决方法。&nbsp;\u003c/p>\u003cp>【自我介绍】各位伙伴大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新知识，共同进步。&nbsp;\u003c/p>\u003cp>【图书介绍：F】今天我分享的内容来自《七堂思维成长课》这本书，它的作者是英国的卡罗琳.韦布。她供职于在全球知名的咨询管理公司——麦肯锡，并在麦肯锡工作了12年，是全球仅有的1%的女性资深合伙人之一。&nbsp;\u003c/p>\u003cp>【图书介绍：A】作者有过非常全面的麦肯锡训练的经历，而且她在麦肯锡也训练了无数的新人，所以同其他同类型的书相比，卡洛琳解读了大量精英人群的实际问题和这些问题的解决方案。而且本书的理论基础比同类的书也更为扎实，作者深入研究了行为科学、心理学和神经科学，研读了600多篇论文和专著，最终形成了一套完成的学习框架。&nbsp;\u003c/p>\u003cp>【图书介绍：B】在书中，作者给职场人士提出了很多的行动建议，可以帮助我们提高执行力，扩大影响力，发现自身的优势，同时也教给我们打造高质量的生活的方法。\r\n今天我们所学习的这部分内容聚焦与制定计划和如何实现目标这部分内容。对每个人职场人士来说，有计划性的工作和生活，按部就班完成目标是一项基础技能，如果这部分基础够扎实，可以助推我们实现职场晋升，也能不断提升自己的行为变现的能力。&nbsp;\u003c/p>\u003cp>【过渡】接下来我们进行一下分组，今天我们人比较少，我们就一组一起讨论。\r\n下面请大家花两分钟的时间阅读一下原文，读完后的请示意我&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":12274,"quote":"\u003cp>我们无法掌控一切，但我们能够做到的是调整工作时间的感受，更用心地设置感知过滤机制。这时候每天坚持设定意图就很有用了，养成这个习惯能让我们留意自己每天的优先事项、关注的事和情绪。\u003cbr> 我的办法如下，花一小段时间从三个角度来考虑(这三个角度的英文都以字母A开头，方便记忆) :\u003cbr> Ø&nbsp; -目标:想想今天活动中最重要的事项、要见的人以及要做的工作。要办成这些事最重要的是什么?那就是你的真实目标。\u003cbr> Ø - 态度:下个工作日要来了，花时间留意并且正视那些支配你思维或情绪的你所关心的事。这些你所关心的事能帮你达成真实目标吗?如果不能，你能暂时把它们放在一边吗?\u003cbr> Ø -关注:从你实际的优先事项出发，你想把精力集中在哪儿?想清楚你想更多看到什么，然后确保自己按计划寻找。\u003cbr> 我共事过的大部分人都认为，最好是在一天开 始前就弄清楚这些问题，可以是在早上或者前一天晚上。但因为这个日常习惯占用的时间不会超过一两分钟， 你从一个任务飞奔到下一一个任务之前再找时间设定意图也不晚。\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>这个片段讲解的是在我们开始做一件事情，或者是在开始一天工作的时候给大脑建立过滤机制的办法。在这里我要解释一下大脑的过滤机制，大脑对于外部复杂的世界只能分配很有限的注意力，在一件事情发生的过程中，大脑就会优先处理他自认为重要的事情，同时把不太重要的事情过滤掉，比如当你集中精力看短信的时候，大脑就会忽略正在与你交谈的同事的话语，当你的同事提高音量，最终到达你的大脑时，你才会突然惊醒，反问道：啊？你刚才说话了？\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>也正是因为这种过滤机制，于是才有了哲学家的那句话：你只会看到你想看到的。所以你会忽略那些在大脑中没有任何意识的事物，那么如果可以在每天，或者是每件事情开始之前，就在大脑中植入那些你更倾向于发生的事情，大脑就会在真实的世界里寻找与你植入的景象更为类似的细节，帮助发现更多的潜在可能性。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：请用自己的语言描述出你的目标。\u003c/strong>\u003cbr> 你到底要去所什么事情，对于这件事情你想要达到什么样的效果？可能是你要去参加一个面试，也可能是公司会议的主持工作，也或者是你要去给你的朋友订一份礼物，不管这个事情是什么，请一定要清楚你的目标，并能通过语言表达出来。\u003cbr> \u003cstrong>第二步：请深呼吸，尝试微笑，把自己调整到最佳的状态。\u003c/strong>\u003cbr> 刚才你已经描述过你的目标了，那在实现目标的过程中，你应该以什么样的状态/态度面对这件事情呢？因为我们面对的事情不一样，所以要实现目标状态也不相同，比如你要主持公司的庆功会，你应该是精神饱满，神采奕奕，充满希望的状态。如果你主持的是公司重大项目总结反思会，那严肃，认真，思考的状态会更加的合适。\u003cbr> \u003cstrong>第三步：请写下在事情进行的过程中你要去关注的细节。\u003c/strong>\u003cbr> 在这件事情完成的过程中，你要关注哪些情况或者，是细节呢？这些也都需要你设想一下，比如，你要去参加一次面试，你就可以提前设想一下，比如，你可能更加关注面试官对你提出的问题，也可能你会更加关注面试官对你的态度举止。这些细节都会让你以更加认真的态度投入到面试中。\u003c/p>\u003cp>\u003cstrong>异议处理\u003c/strong>\u003c/p>\u003cp>或许有人会问这真的管用吗？只要在大脑中建立了过滤机制，事情就会朝我们想要的方向发展？这里需要说明的是：事情当然是因为人们的行为而改变的，给大脑设置过滤机制是给注意力提供了方向，大脑会优先注意到与过滤机制更类似的信息，而我们的行为就是受到这些信息所左右的。\u003c/p>","interaction":"\u003cp>\u003cstrong>激活A1\u003c/strong>\u003c/p>\u003cp>现在请大家回忆一下，在你的过去的工作或者生活中，有没有发生过类似这样的事情——你被安排去做某件事情，你一听就觉得：天哪，怎么会给我安排这件事情呢，这事儿怎么能做好呢？但是没办法你只能去做，结果真的是按照你预想的样子，很糟糕。大家有印象发生过这样的事情么？\u003c/p>\u003cp>\u003cstrong>分享\u003c/strong>\u003c/p>\u003cp>上周跟我们领导去唐山出差么，晚上他来敲我的门，要我陪他去跑步，我当时没准备，心想这大晚上的去跑什么啊,自己当时其实就觉得不是特别的好,但是领导在那等我呢,我也不能说不去,我一看这样,那就去吧,我就带上我的小宝,带上手机,就出门了,我当时没有察觉,其实我当时身上还挂着蓝牙耳机,还有一串钥匙,结果我出去跟领导跑步的时候,嘀哩当啷的,我们也就跑了十几二十分钟,我们领导跟我说,你别跑了,我自己把剩下的跑完吧.然后他就自己去跑了\u003c/p>\u003cp>\u003cstrong>让学习者加工A1+\u003c/strong>\u003c/p>\u003cp>看来大家也都有过类似的经历，而且那件事情也给各位留下了比较深刻的印象，那么现在在请大家思考一下，此刻你已经学会了给大脑建立过滤机制的方法，三步：设目标，调状态，写下关注细节。\u003cbr>假如可以回到当时的情景，运用今天你学到的用给大脑设立过滤机制的方法，你会怎么做？我们讨论一下，一会我们会找小伙伴分享。\u003c/p>\u003cp>\u003cstrong>分享A1+\u003c/strong>\u003c/p>\u003cp>如果在能会到当时,我肯定不会是刚才我说的样子了.其实我的目标应该是让领导开心么,因为当时也是跟着领导去出差,这一路上也是以他为圆心,所以我的第一步目标就是让领导开心,然后我的状态应该更加积极,主动问一下领导晚上有什么活动,那他说要去跑步,那么我晚上就少吃点,保证足够的这种精神头,最后在细节上我会注意一下当时我当时穿的衣服啊,不要带太多的小东西在身上啊,跑步的时候尽量要轻松,跟上领导的步伐等等.\u003c/p>\u003cp>\u003cstrong>过渡\u003c/strong>\u003c/p>\u003cp>感谢我师父的分享，这就是在大脑中建立过滤机制带来的好处，我们会调动一切的能力来促使事情发展得更加顺利。\u003cbr>那我们一起来回顾一下在刚才的第一个拆页中，我们讲的是针对某件事情，如果在大脑中用过滤机制把这件事情朝积极的方向过滤一遍，可能就会更好的帮助我们顺利完成这件事情。\u003c/p>\u003cp>\u003cstrong>提问1：\u003c/strong>大家还记得这三个步骤是什么么？\u003cbr>\u003cstrong>学习者回答：\u003c/strong>设目标，调状态，写下关注细节。\u003cbr>非常感谢大家的反馈，看来大家都记得很清楚。其实这三步对于我们每个人来说都不是很难,但是想要真的学会给大脑建立过滤机制,还要各位多多练习.\u003c/p>\u003cp>而且在这三步中有一步非常的关键,那就是关于目标的这部分内容,相信我们大家都经历过这样的情况：虽然我们有目标，我们也能把目标描述出来，但，并不一定能促使我们达成目标。在我们与目标之间总会有重重的障碍。对于这些障碍，我们没有办法无视它，这时候我们应该如何这是目标,需要注意哪些点呢?接下来我们一起来看第二个片段.给大家一分钟的时间,看一下来看一下第二个片段.\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":12275,"quote":"\u003cp>\u003cstrong>第二个原文\u003c/strong>\u003c/p>\u003cp>最后，为保证完成目标，需要非常细致地理清我们要做什么，以及何时做。举例来说，比较奥黛丽下面两个版本的目标：\u003cbr> -我要在今天的谈话中表现得更配合。\u003cbr> -\u003cstrong>如果对方皱眉或提出问题，那么我要停下来仔细倾听，然后通过提问来了解更多情况。\u003c/strong>\u003cbr> 你觉得哪一个版本能让她更明确地知道具体应该怎么做呢？显然，第二个更确切，更容易做到，不是么？\u003c/p>","explains":"\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>在这一段文字中，举例说明要实现目标，可以有两种做法，第一种做法是告诉自己如何做，第二种做法是设想在实现目标过程中出现的障碍，并针对这个障碍提出解决方法。同时，这段文字也告诉我们第二种方法会更容易帮助我们实现目标。\u003cbr> 在实现目标的过程中，思考可能会出现的障碍，能让我们直面这些困难。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>我们不是魔法师，我们遇到的事情事情不会完全按照我们的设想的样子来发展，那么在设置目标的时候，不妨思考一下消极的地方，这样我们便可以提前一步想到应对困难的方法，有充足的时间预防突发事件，不会让自己措手不及。\u003c/p>\u003cp>\u003cstrong>意译案例\u003c/strong>\u003c/p>\u003cp>刚才原文片段给出的案例是工作中的,那么我们来举一个生活中的案例,大家来一起体会一下:\u003c/p>\u003cp>为了保证达成任务，需要极为认真的思考清楚我们要做什么，以及如何做。举例来说：\u003c/p>\u003cp>比较我的下面两个版本的目标：\u003c/p>\u003cp>——我要让我爱人做饭,下班之后给他打电话时,我要表现得更有耐心;\u003c/p>\u003cp>——如果我爱人不知道做什么饭或者直接让我在外面吃,那么我就把自己想吃的菜列给他,然后撒娇告诉他我只想吃他做的饭.\u003c/p>\u003cp>你觉得哪一个版本能让我更明确的知道具应该怎么做呢？显然，第二个更有效，更好做到，不是么？\u003c/p>\u003cp>\u003cstrong>细化步骤How\u003c/strong>\u003c/p>\u003cp>那第二种做法到底应该如何实现呢？\u003cbr> \u003cstrong>第一，把你要实现的目标写下来。\u003c/strong>\u003cbr> 如果你的目标足够明确，能够正确的表达你的目标，也会帮助你成功。这一步能够帮助你更全面的看清楚你要做到什么程度，达到什么效果。\u003cbr> \u003cstrong>第二，思考达成目标的过程中可能出现的障碍。\u003c/strong>\u003cbr> 在完成目标的过程中，你能预见到可能会在什么时间出现什么样的困难，就可以提前做出准备，以此来帮助你可以避开、解决困难，顺利达成目标。\u003cbr> \u003cstrong>第三，用“如果...那样...”的方法来做好预备方案。\u003c/strong>\u003cbr> 关于“如果...那样...”规则我们可以这样理解：如果发生了X的情况，那么我就采取Y行动。这一步是在未来可能发生的困难和采取行动之间搭建了一座桥梁，让我们更好的解决掉可能会出现的障碍，顺利达到自己想要的结果。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一般情况下的做法：\u003c/strong>\u003c/p>\u003cp>可能有人会说生活中这么做，太累了，以前我不这么做，也没有任何影响啊。通常情况下，人们在实现目标的时候，是没有思考过“如果发生什么事情，那么我会采取什么行动”这个方法的。\u003c/p>\u003cp>\u003cstrong>这样做的坏处：\u003c/strong>这样做的坏处：所以，在实现目标的过程中如果出现障碍、困难，人们就会觉得很意外，手足无措，开始抱怨前期没有做好准备。\u003c/p>\u003cp>\u003cstrong>一般情况下的做法的例子\u003c/strong>：比如小明女朋友最近在锻炼身体，小明就约女朋友周末去爬山。结果周末的时候大晴天，气温38度，小明没办法只能在当天早上取消了约会。\u003cbr> \u003cstrong>正例：\u003c/strong>设想一下小明当时思考过“如果发生什么事情，那么我会采取什么行动”这个方法的话，那小明会想：如果周末天气适宜，那么我就约女朋友去爬山，如果天气很热或者是下雨，那么我就约女朋友去玩室内攀岩。\u003cbr> 你看，其实这个过程并不复杂，或许你只需要多思考十几秒钟的时间。假设我们能够很好的利用“如果…那么…”这个方法”，我们在做事情的时候，就会有针对可能出现的问题的预备方案，从而更好的解决可能会出现的问题，帮助我们实现预想的目标。\u003c/p>\u003cp>\u003cstrong>异议处理\u003c/strong>\u003c/p>\u003cp>还有小伙伴会问，“如果...那么..”的情况经常发生，从小我们就用这个学习造句，这根本算不上是什么方法，最直接的，我们常说“如果他不同意，那么我们就不做了”。\u003cbr> 在这里我需要去提醒大家的是“如果...那么...”这个方法是为你前面设置的目标而服务的，最终的目的是为了帮助目标的达成。而在现实生活中大家常说的“如果...那么...”已经改换了目标。\u003cbr> 我们举个例子，比如今天中午你的目标是吃一碗面，按照片段中“如果...那么...”的方法应该说：“如果A饭馆没有油泼面，那么我就去B饭馆吃”，而实际生活中我们说的是：“如果没有油泼面，那我就吃炒米饭”，我们会发现目标已经改变了\u003c/p>","interaction":"\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>小组讨论:\u003c/strong>\u003c/p>\u003cp>学习了“如果…那么…”的这个方法后，下面我们来做一个案例研讨。\u003c/p>\u003cp>小M最近研发了一个新样品,新品更加的时尚,小巧,适合当代年轻人的审美,而且也更加的结实,耐用了,虽然相较与老产品成本和人工都有所增加,仍然是得到了部门领导的认可,所以准备在公司新品会议上推出,各部门一起讨论一下优化产品方案,批量生产,发行.\u003c/p>\u003cp>一些同期进公司的同事，看到小M做出了新品，得到了领导的赏识,很不服气，日常工作中就出现刁难他，估计在新品会上也会发难，小M本身性子就急，又不善言谈，面对这种情况，你作为会议主持人，你的目标会是什么？可能会出现哪些障碍，又如何应用“如果…那么…”来完成这个目标呢？\u003c/p>\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>讨论:\u003c/strong>\u003c/p>\u003cp>目标: 按流程进行,整个会议围绕新样品进行客观,公正的讨论,\u003c/p>\u003cp>可能出现的障碍：1、会议可能会偏离主题，比如有人可能认为新品并不符合当代年轻人的审美，进而变成了大家去讨论“当代年轻人的审美是什么样子的”\u003c/p>\u003cp>2、会议中可能会因新品的成本及人工增加这一点卡住，\u003c/p>\u003cp>3、会议中有同期的同事因新样品的缺点对小M发难，小M可能会控住不住自己的性子愤然离席，或发生其他不好的事件，\u003c/p>\u003cp>解决：如果会议偏离主题，那么我就及时叫停，把大家拉回当下正在讨论的内容上；如果会议因成本和人工问题耽误太久的时间，那么我要在会前带上小M与财务和生产部门的人沟通，让他们先完成这部分内容的讨论；如果会议中出现了有人针对小M的发难，那么我会先与小M沟通，让他提前做好准备，不要愤然离席，也不要被他人的问题左右。最终要通过会议讨论出新样品的优化方案，为后期批量生产做好基础。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>应用催化：\u003c/strong>\u003c/p>\u003cp>非感谢小伙伴的分享，接下来请大家想一想自己在未来的一周或者是一个月之内，会不会遇到这样的场景：在你和家人的沟通过程中，家人可能会否定你的想法；在工作中，可能会有同事拒绝你的请求；或者是当你在和朋友一起的时候，朋友会不同意你的决定；你会遇到什么样的场景呢？\u003c/p>\u003cp>\u003cstrong>讨论：\u003c/strong>\u003c/p>\u003cp>我可能会遇到家人的沟通障碍：跟我爱人就我工作的问题，他会否定我的想法。\u003c/p>\u003cp>\u003cstrong>解决问题：\u003c/strong>\u003c/p>\u003cp>在这个过程中你的目标可能是什么？会出现哪些障碍？请你用“如果...那么...”的方法解决问题。\u003c/p>\u003cp>\u003cstrong>讨论：\u003c/strong>\u003c/p>\u003cp>因为最近我在休假，但是我们领导还是找到我，让我干活，我不想做，我爱人就觉得我不对。我很早就想找他沟通这个问题，但是最近我们都比较忙。\u003c/p>\u003cp>我的目标就是：他能支持我的想法\u003c/p>\u003cp>可能会遇到的障碍：1，他觉得这就是我的工作，在其位谋其政，2、他觉得我在拆书上付出的努力都比工作上的多。\u003c/p>\u003cp>解决：今晚回去我就要跟他沟通，如果他觉得这是我的工作，那么我首先同意他的想法，同时我也要告诉他，我现在是休假时间，领导完全可以把工作派给其他人，他只不过是因为给我排货派顺手了，总是捡着软柿子捏；如果他认为我在拆书上付出的努力都比工作上的多，那么我要告诉他，拆书学习是我快乐的源泉，而且我很有收获，一直在成长，所以我会付出很多努力。\u003c/p>\u003cp>\u003cstrong>回应与反馈\u003c/strong>\u003c/p>\u003cp>非常感谢陈陈姐的分享，运用这个方法，确实可以帮助我们避免与家人，或者是朋友，同事之间一些争议，希望这个方法可以帮助到大家。\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>非常感谢大家的积极参与。\u003cbr> 今天我们首先学习了通过进行大脑的过滤机制的设置这个方法，使我们顺利获得了自己想要的结果。然后我们学习的是通过“心理对照”的学习，促使我们在积极心态的同时去预想困难是什么，再用“如果..那么..”的方法来克服，这样面对困难，我们就会有更多的准备，从而更顺利的实现自己的目标。\u003cbr> 相信这些方法一定可以在实际生活中帮助到我们，促使我们升职加薪，当上总经理出任CEO，迎娶白富美，走上人生巅峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1565255019000,"updated_at":1565255196000,"ria":true},{"id":8406,"topic":"制定计划和如何实现目标","learn_goal":"有计划性的工作和生活，提高行为变现的能力。","remark":"当遇到重要事情的时候，可以制定出顺利完成任务的计划。","level":"TF2-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"【自我介绍】各位伙伴大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新知识，共同进步。\r\n【图书介绍：F】今天我分享的内容来自《七堂思维成长课》这本书，它的作者是英国的卡罗琳.韦布。她供职于在全球知名的咨询管理公司——麦肯锡，并在麦肯锡工作了12年，是全球仅有的1%的女性资深合伙人之一。\r\n【图书介绍：A】作者有过非常全面的麦肯锡训练的经历，而且她在麦肯锡也训练了无数的新人，所以同其他同类型的书相比，卡洛琳解读了大量精英人群的实际问题和这些问题的解决方案。而且本书的理论基础比同类的书也更为扎实，作者深入研究了行为科学、心理学和神经科学，研读了600多篇论文和专著，最终形成了一套完成的学习框架。\r\n【图书介绍：B】在书中，作者给职场人士提出了很多的行动建议，可以帮助我们提高执行力，扩大影响力，发现自身的优势，同时也教给我们打造高质量的生活的方法。\r\n今天我们所学习的这部分内容聚焦与制定计划和如何实现目标这部分内容。对每个人职场人士来说，有计划性的工作和生活，按部就班完成目标是一项基础技能，如果这部分基础够扎实，可以助推我们实现职场晋升，也能不断提升自己的行为变现的能力。\r\n【过渡】接下来我们进行一下分组，我们今天分为两组，我的左手边一组，右手边一组。\r\n下面请大家花两分钟的时间阅读一下原文，读完后的请示意我。","ratings_count":1,"texts":[{"id":12050,"quote":"\u003cp>我们无法掌控一切，但我们能够做到的是调整工作时间的感受，更用心地设置感知过滤机制。这时候每天坚持设定意图就很有用了，养成这个习惯能让我们留意自己每天的优先事项、关注的事和情绪。\u003cbr> 我的办法如下，花一小段时间从三个角度来考虑(这三个角度的英文都以字母A开头，方便记忆) :\u003cbr> Ø&nbsp; -目标:想想今天活动中最重要的事项、要见的人以及要做的工作。要办成这些事最重要的是什么?那就是你的真实目标。\u003cbr> Ø - 态度:下个工作日要来了，花时间留意并且正视那些支配你思维或情绪的你所关心的事。这些你所关心的事能帮你达成真实目标吗?如果不能，你能暂时把它们放在一边吗?\u003cbr> Ø -关注:从你实际的优先事项出发，你想把精力集中在哪儿?想清楚你想更多看到什么，然后确保自己按计划寻找。\u003cbr> 我共事过的大部分人都认为，最好是在一天开 始前就弄清楚这些问题，可以是在早上或者前一天晚上。但因为这个日常习惯占用的时间不会超过一两分钟， 你从一个任务飞奔到下一一个任务之前再找时间设定意图也不晚。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>希望大家在学习完这个内容之后，当你再遇到重要事情的时候，不再是被事情推着走，而是可以使用给大脑建立过滤机制的方法，帮助自己设计出一个顺利完成任务的计划。\u003c/p>\u003cp>【What】\u003cbr>\u003c/p>\u003cp>这个片段讲解的是在我们开始做一件事情，或者是在开始一天工作的时候给大脑建立过滤机制的办法。在这里我要解释一下大脑的过滤机制，大脑对于外部复杂的世界只能分配很有限的注意力。在一件事情发生的过程中，大脑就会优先处理他自认为重要的事情，同时把不太重要的事情过滤掉，比如当你集中精力看短信的时候，大脑就会忽略正在与你交谈的同事的话语，当你的同事提高音量，最终到达你的大脑时，你才会突然惊醒，反问道：啊？你刚才说话了？\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>也正是因为这种过滤机制，于是才有了哲学家的那句话：你只会看到你想看到的，而忽略了那些大脑中没有任何意识的事物，所以如果可以在每天，或者是每件事情开始之前，就在大脑中植入那些你更倾向于发生的事情，大脑就会在真实的世界里寻找与你植入的景象更为类似的细节，帮助发现更多的潜在可能性。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>\u003cstrong>第一步：请用自己的语言描述出你的目标。\u003c/strong>\u003cbr> 你到底要去所什么事情，对于这件事情你想要达到什么样的效果？可能是你要去参加一个面试，也可能是公司会议的主持工作，也或者是你要去给你的朋友订一份礼物，不管这个事情是什么，请一定要清楚你的目标，并能通过语言表达出来。\u003cbr> \u003cstrong>第二步：请深呼吸，尝试微笑，把自己调整到最佳的状态。\u003c/strong>\u003cbr> 刚才你已经描述过你的目标了，那在实现目标的过程中，你应该以什么样的状态/态度面对这件事情呢？因为我们面对的事情不一样，所以要实现目标状态也不相同，比如你要主持公司的庆功会，你应该是精神饱满，神采奕奕，充满希望的状态。如果你主持的是公司重大项目总结反思会，那严肃，认真，思考的状态会更加的合适。\u003cbr> \u003cstrong>第三步：请写下在事情进行的过程中你要去关注的细节。\u003c/strong>\u003cbr> 在这件事情完成的过程中，你要关注哪些情况或者，是细节呢？这些也都需要你设想一下，比如，你要去参加一次面试，你就可以提前设想一下，比如，你可能更加关注面试官对你提出的问题，也可能你会更加关注面试官对你的态度举止。这些细节都会让你以更加认真的态度投入到面试中。\u003c/p>\u003cp>【异议处理】\u003cbr>\u003c/p>\u003cp>或许有人会问这真的管用吗？只要在大脑中建立了过滤机制，事情就会朝我们想要的方向发展？这里需要说明的是：事情当然是因为人们的行为而改变的，给大脑设置过滤机制是给注意力提供了方向，大脑会优先注意到与过滤机制更类似的信息，而我们的行为就是受到这些信息所左右的。\u003c/p>","interaction":"\u003cp>【激活A1】\u003c/p>\u003cp>现在请大家回忆一下，在你的过去的工作或者生活中，有没有发生过类似这样的事情——你被安排去做某件事情，你一听就觉得：天哪，怎么会给我安排这件事情呢，这事儿怎么能做好呢？但是没办法你只能去做，结果真的是按照你预想的样子，很糟糕。大家有印象发生过这样的事情么？\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>有，刚过去的七一，我们单位说要组织学习，我们办公室主任突然找到我说，让我负责这个事情，当时一下子头就大了，不知道为什么领导安排给我，因为我从来没有负责过这种事情，也不知道从哪里请老师，后续的工作怎么对接，我也不太清楚，但也没办法推脱，心情就很烦躁，觉得做不好。有个朋友给我介绍了一个学校的伙伴，又通过这个伙伴才联系到了老师，后来在联系过程中，磕磕绊绊，最后讲课结束之后，又因为开票的问题，弄得很繁琐，果然就没有做好，事情不顺利。\u003c/p>\u003cp>【加工的A1+】\u003c/p>\u003cp>听刚才大家的分享，尤其是我们子蹊的分享，看来大家也都有过类似的经历，而且那件事情也给各位留下了非常深刻的印象，那么现在在请大家思考一下，此刻你已经学会了给大脑建立过滤机制的方法，三步：设目标，调状态，写下关注细节。\u003cbr>假如可以回到当时的情景，或者以后你在遇到类似的情况，运用今天你学到的用给大脑设立过滤机制的方法，你会怎么做？我们讨论一下，一会我们会找小伙伴分享。\u003c/p>\u003cp>【分享者的A1+】\u003c/p>\u003cp>假如可以回到当时的情景，或者以后你在遇到类似的情况，首先我树立的目标是：我要跟自己说：一定要组织好这次授课。然后我会调整一下自己的状态：因为我以前没有组织过，所以这次对我来说是一个特别好的学习和锻炼的机会，如果这次我能组织好，代表我的组织能力和沟通协调能力都在成长。最后我会罗列其中的一些需要我特别关注的细节：比如，我会列出一些问题：1、具体的组织课程的流程是什么样子的，2、对老师的要求及去哪里请老师，3、对接老师的某些细节，这里或许就包括了后续的开票问题，4、谁有这方面的经验可以让我去请教等等。\u003c/p>\u003cp>那么整个过程下来，我想一定会朝着我努力的方向去发展的。\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>感谢这位小伙伴的分享，这就是在大脑中建立过滤机制带来的好处，我们会调动一切的能力来促使事情发展得更加顺利。\u003cbr> 那我们一起来回顾一下在刚才的第一个拆页中，我们讲的是针对某件事情，如果在大脑中用过滤机制把这件事情朝积极的方向过滤一遍，可能就会更好的帮助我们顺利完成这件事情。\u003c/p>\u003cp>【回应与反馈】\u003cbr>我提问：大家还记得这三个步骤是什么么？\u003cbr>学习者回答：设目标，调状态，写下关注细节。\u003cbr> 非常感谢大家的反馈，看来大家都记得很清楚。\u003cbr>我提问：那在这三步骤中，大家觉得哪一步最难呢？\u003cbr>学习者回答：调整状态会比较困难吧\u003c/p>\u003cp>我提问：是这样子的么？很多时候，我们在面临某种状态的时候，可能我们本身的状态并不差，很有劲头，同时却不知道朝哪个方向走，那大家换个角度想一下，如果我们知道自己要朝哪个方向走，做到什么程度，是不是也会慢慢的调整自己的状态？那跟你这个目标相关的某些细节，你自然也就会更加的留心？大家觉得到底是哪一步比较困难呢？\u003c/p>\u003cp>学习这回答：哦~确实是的，很多时候，自己一把劲却不知道目标在哪里，一身劲都没处使，是第一步关于目标这一步比较有难度。\u003c/p>\u003cp> 我提问：这么一说其实大家就都有感觉了，是吧？大家可以静下来想一想，有没有经历过这种情况，就是我们在做关于目标的这一步时，如果我们只是把目标描述出来，并不一定促使我们达成目标。在我们与目标之间总会有重重的障碍。对于这些障碍，我们没有办法无视它，但又随时可能发生，大家遇到过这种情况么？\u003c/p>\u003cp> 【学习这回答】经常遇到\u003cbr> 【过渡】这时我们应该如何设置目标呢？需要注意哪些点呢？\u003cbr> 接下来我们来看第二个片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":12052,"quote":"\u003cp>最后，为保证完成目标，需要非常细致地理清我们要做什么，以及何时做。举例来说，比较奥黛丽下面两个版本的目标：\u003cbr> -我要在今天的谈话中表现得更配合。\u003cbr> -\u003cstrong>如果对方皱眉或提出问题，那么我要停下来仔细倾听，然后通过提问来了解更多情况。\u003c/strong>\u003cbr> 你觉得哪一个版本能让她更明确地知道具体应该怎么做呢？显然，第二个更确切，更容易做到，不是么？\u003c/p>","explains":"\u003cp>【学习目标】\u003cbr>\u003c/p>\u003cp>在学习完这个片段之后，希望你下次在设置目标的时候，能够预想到目标实现过程中可能出现的困难，并且把问题写下来再用，用“如果...那么...”的方法寻找到解决方法。\u003c/p>\u003cp>【What】\u003cbr>\u003c/p>\u003cp>在这一段文字中，举例说明要实现目标，可以有两种做法，第一种做法是告诉自己如何做，第二种做法是设想在实现目标过程中出现的障碍，并针对这个障碍提出解决方法。同时，这段文字也告诉我们第二种方法会更容易帮助我们实现目标。\u003cbr> 在实现目标的过程中，思考可能会出现的障碍，能让我们直面这些困难。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>我们不是魔法师，我们遇到的事情事情不会完全按照我们的设想的样子来发展，那么在设置目标的时候，不妨思考一下消极的地方，这样我们便可以提前一步想到应对困难的方法，有充足的时间预防突发事件，不会让自己措手不及。\u003c/p>\u003cp>【细化步骤：How】\u003c/p>\u003cp>那第二种做法到底应该如何实现呢？\u003cbr> \u003cstrong>第一，把你要实现的目标写下来。\u003c/strong>\u003cbr> 如果你的目标足够明确，能够正确的表达你的目标，也会帮助你成功。这一步能够帮助你更全面的看清楚你要做到什么程度，达到什么效果。\u003cbr> \u003cstrong>第二，思考达成目标的过程中可能出现的障碍。\u003c/strong>\u003cbr> 在完成目标的过程中，你能预见到可能会在什么时间出现什么样的困难，就可以提前做出准备，以此来帮助你可以避开、解决困难，顺利达成目标。\u003cbr> \u003cstrong>第三，用“如果...那样...”的方法来做好预备方案。\u003c/strong>\u003cbr> 关于“如果...那样...”规则我们可以这样理解：如果发生了X的情况，那么我就采取Y行动。这一步是在未来可能发生的困难和采取行动之间搭建了一座桥梁，让我们更好的解决掉可能会出现的障碍，顺利达到自己想要的结果。比如我和小溪沟通团队出游的事情，我的目标是让小溪同意现在的出游方案，障碍点可能是：小溪可能不同意去很多同事选择的宁波。接下来是我的思考：如果在沟通过程中，小溪对出游地点有异议，那么我就拿旅行社给的报价给他，告诉他其实在这个季节，不管去哪里费用都差不多，如果小溪对出游的地点还是有意义，那么我会建议采用投票的方式解决这个问题。这就是“如果...那样...”的应用。\u003c/p>\u003cp>【意义案例】\u003c/p>\u003cp>“如果-那么”这个方法其实很好用，说一个我自己的经历：\u003cbr> 下班的路上，我希望我回到家里就能吃上热腾腾的饭菜，不用我再做饭了。为实现这个目标，我有两种想法：\u003cbr> -给我爱人打电话让他回家做饭\u003cbr> -如果我爱人以不知道做什么好为借口推脱这件事情，那么我就列好他会做的几样菜，同时告诉他我有点不舒服，想吃点可口的饭菜。\u003cbr> 相比之下，当然是“如果…那么…”这后一种方法更有效了。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>\u003cstrong>一般情况下的做法：\u003c/strong>\u003c/p>\u003cp>可能有人会说生活中这么做，太累了，以前我不这么做，也没有任何影响啊。通常情况下，人们在实现目标的时候，是没有思考过“如果发生什么事情，那么我会采取什么行动”这个方法的。\u003c/p>\u003cp>\u003cstrong>这样做的坏处：\u003c/strong>这样做的坏处：所以，在实现目标的过程中如果出现障碍、困难，人们就会觉得很意外，手足无措，开始抱怨前期没有做好准备。\u003c/p>\u003cp>\u003cstrong>一般情况下的做法的例子\u003c/strong>：比如小明女朋友最近在锻炼身体，小明就约女朋友周末去爬山。结果周末的时候大晴天，气温38度，小明没办法只能在当天早上取消了约会。\u003cbr>\u003cstrong>正例：\u003c/strong>设想一下小明当时思考过“如果发生什么事情，那么我会采取什么行动”这个方法的话，那小明会想：如果周末天气适宜，那么我就约女朋友去爬山，如果天气很热或者是下雨，那么我就约女朋友去玩室内攀岩。\u003cbr> 你看，其实这个过程并不复杂，或许你只需要多思考十几秒钟的时间。假设我们能够很好的利用“如果…那么…”这个方法”，我们在做事情的时候，就会有针对可能出现的问题的预备方案，从而更好的解决可能会出现的问题，帮助我们实现预想的目标。\u003c/p>\u003cp>【异议处理】\u003c/p>\u003cp>还有小伙伴会问，“如果...那么..”的情况经常发生，从小我们就用这个学习造句，这根本算不上是什么方法，最直接的，我们常说“如果他不同意，那么我们就不做了”。\u003cbr> 在这里我需要去提醒大家的是“如果...那么...”这个方法是为你前面设置的目标而服务的，最终的目的是为了帮助目标的达成。而在现实生活中大家常说的“如果...那么...”已经改换了目标。\u003cbr> 我们举个例子，比如今天中午你的目标是吃一碗面，按照片段中“如果...那么...”的方法应该说：“如果A饭馆没有油泼面，那么我就去B饭馆吃”，而实际生活中我们说的是：“如果没有油泼面，那我就吃炒米饭”，我们会发现目标已经改变了\u003c/p>","interaction":"\u003cp>【小组讨论】\u003c/p>\u003cp>学习了“心理对照”以及“心理对照”的应用，下面我们来做一个案例研讨。小北是个单身男生，周围所有的亲戚朋友都觉得小伙能挣钱，脾气好，颜值高，纷纷为他的婚事着急，而小北对自己的状态很知足，觉得单不单身不重要，重要的是活得开心。他的母亲告诉他，有亲戚想给他介绍了对象，小北面对这种情况陷入了思考，\u003cbr> 请各位伙伴思考一下，小北此刻他的目标是什么？如何应用“如果…..那么…..”来帮助自己实现目标。\u003c/p>\u003cp>【分享者】\u003c/p>\u003cp>小北的目标是：活的开心。所以按照小北的这个目标，那么，为了开心，他不会喜欢父母及亲戚朋友的唠叨，而且，小北觉得“单不单身不重要”也就是小北并不反对谈恋爱，所以：\u003c/p>\u003cp>如果父母和亲戚朋友想让他去相亲，为不被唠叨，那么他就去相亲；\u003c/p>\u003cp>如果他对相亲对象比较满意，觉得两个人在一起会更开心，那么就试着相处；\u003c/p>\u003cp>如果对方他不太满意，那么就拒绝，回去告诉父母对方不太合适，自己也不是很着急谈恋爱；\u003c/p>\u003cp>如果父母仍旧给他安排相亲，那么就继续见面；\u003c/p>\u003cp>【A2应用催化】\u003cbr>\u003c/p>\u003cp>非感谢小伙伴的分享，我想这样小北应该就可以放松了。接下来请大家想一想自己在未来的一周或者是一个月之内，会不会遇到这样的场景：在你和家人的沟通过程中，家人可能会否定你的想法；在工作中，可能会有同事拒绝你的请求；或者是当你在和朋友一起的时候，朋友会不同意你的决定；你会遇到什么样的场景呢？\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>会和家人遇到这样的场景：我给孩子买了很多书让孩子读，家里人觉得孩子学业很重，反对我的做法。\u003c/p>\u003cp>【解决问题】\u003cbr>\u003c/p>\u003cp>在这个过程中你的目标可能是什么？会出现哪些障碍？请你用“如果...那么...”的方法解决问题。\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>我的目标是让孩子通过读书，丰富对这个世界的认知，而且还能提高他的阅读兴趣。\u003c/p>\u003cp>如果家人觉得孩子课业太重，不想让孩子读我给买的书，那么我就把书分类，先给孩子读一些与他的课程比较相近的课外书籍，这样的话孩子好接受，不那么辛苦；\u003c/p>\u003cp>如果家里人还是不同意，那么我就把孩子每天的作息时间规定出一小段时间专门用于读书，比如晚上读半个小时，这样时间不会太久，孩子也不会太累；\u003c/p>\u003cp>如果家人还是觉得孩子很辛苦，我就把学习时间在缩短一些，同时跟家里人沟通一下阅读的好处，比如：丰富认知能力，提升理解能力，表达能力等等，相信会取得家里人的同意的。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>非常感谢这位小伙伴的分享，希望这个方法可以帮助到大家。也非常感谢大家的积极参与。\u003cbr> 今天我们首先学习了通过进行大脑的过滤机制的设置这个方法，使我们顺利获得了自己想要的结果。然后我们学习的是通过“心理对照”的学习，促使我们在积极心态的同时去预想困难是什么，再用“如果..那么..”的方法来克服，这样面对困难，我们就会有更多的准备，从而更顺利的实现自己的目标。\u003cbr> 相信这些方法一定可以在实际生活中帮助到我们，促使我们升职加薪，当上总经理出任CEO，迎娶白富美，走上人生巅峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1563171795000,"updated_at":1563171795000,"ria":true},{"id":7882,"topic":"沟通效率！","learn_goal":"学会如何积极地说“不”","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"流觞","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 自我介绍一下，我是流觞，我的职业是一名电信的工程师。平时喜欢读小说和心理管理类书籍，除此之外，最大的爱好是街舞。\r\n为了方便稍后的学习，我们先分下组，3个人一组，刚好分3组。\r\n今天带来的的书是《七堂思维成长课：精英群体的行为习惯》，作者是卡罗琳·韦布，作者在麦肯锡工作了12年，培训过无数新人，积累了大量实际案例和工作经验。作者把职场人士工作中可能应对的诸多麻烦，化简成七堂课，深度剖析了精英人群如何安排自己的生活，面对负面情绪，结交和管理人脉，最终打造属于自己的高质量生活。所以，这是一本精英工作行为指南书。\u003c/p>","ratings_count":1,"texts":[{"id":11426,"quote":"\u003cp>我们谈到了每天的工作时间有限，所以你不可能所有事情都做。每次你对一个请求说“是”、实际上就在对其他事情说“不”。所以你的肯定回答一定要针对重要的、缺你不行的事情。但要集中时间和精力办事的一个普遍障碍是，我们都不想拒绝向我们提要求的那个人婉拒也很难说出口。“我不喜欢冲突，也不希望让别人失望，”安东尼说，“所以我觉得说‘不’很难，如果是不得不拒绝的情况，在打电话或走进会场前我都会精神紧张。”\u003c/p>\u003cp>这就是“积极地拒绝”这个办法的用武之地了。如果你发现自己很难从较低优先度的事情中抽身，那么学着如何积极地说“不”就像发现了新的超能力一一能让所有人对你做的决定如沐春风（包括你自己）。\u003c/p>\u003cp>为了提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如：\u003c/p>\u003cp>⒈热情开场。首先认可并且赞许对方的请求。\u003c/p>\u003cp>⒉你的“是”。然后，不要以“真的很抱歉……”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003c/p>\u003cp>⒊你的“不”。解释清楚情況，表达遗憾之意，意思就是你无法答应他们的请求。\u003c/p>\u003cp>⒋温情结尾。也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结束语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>","explains":"\u003cp>求人帮忙和帮别人的忙是日常工作与生活中经常会遇到的事，然而有的忙我们不想帮，或者是实在帮不了的时候，拒绝向我们提要求的人，却又害怕把关系弄得很紧张。你希望通过婉拒期待对方能理解和支持，但人们听到发出消极信号的“真的很抱歉……”表达，还是会让对方高度戒备，你就很难获得理解。\u003c/p>\u003cp>这时，“积极的拒绝”是一种很好的表达方法。通过积极的语言信号开头表达，然后再深入表达自己想说的，最后表示遗憾之意和热情祝愿对方项目成功，能让所有人对你的决定表示认同。\u003c/p>\u003cp>具体的做法如下：\u003c/p>\u003cp>首先，热情的回应对方的请求；\u003c/p>\u003cp>第二，解释缘由，让对方认可自己正在处理工作重要性；\u003c/p>\u003cp>第三，表达遗憾无法答应对方的请求；\u003c/p>\u003cp>最后，热情祝愿对方项目成功。\u003c/p>\u003cp>在委婉拒绝的同时，主动加上替代方案，也会给人留下正面积极、想帮助对方解决问题的印象。\u003c/p>\u003cp>先举一个我自己的例子：我前几天晚上到客户公司处理业务，当业务处理好的时候，公司又派来其他的业务，我这时就对客户说：“业务已经完成，你这边派人检查一遍，我还有其他事就先撤了。“客户提要求说必须等他们工程师检查完才能离开。等他们工程师检查完起码需要半个小时，我再次和客户沟通说：很抱歉，我这里确实有急事，等不了那么长时间。\u003cbr>\u003c/p>\u003cp>这样的表达还是无法获得客户的理解\u003c/p>\u003cp>运用拆页积极的拒绝如下：\u003c/p>\u003cp>首先，您提出的要求非常合理，我内心是赞成您的决定。\u003c/p>\u003cp>其次，您也清楚，现在是晚上，非法定工作时间我们还在值班就是为了处理客户的业务中断等突发情况的发生，顾客满意是公司的一贯宗旨，高效及时处理故障是我们的职责所在。\u003c/p>\u003cp>现在，另一家用户业务出现问题，为了及时处理，我需要提前离开，请您谅解。\u003c/p>\u003cp>最后，如果您公司的工程师在检查过程中发现问题，您可以联系网管中心帮您查看。\u003c/p>\u003cp>很高兴为您服务，希望您工作顺利，生活愉快。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>请大家回想下自己在生活或者工作中，朋友或者同事向你提出难以接受的要求，你是如何回应的。你的回应是否令对方满意，请大家写在便签上，并在在小组内分享，限时2min。\u003c/p>\u003cp>分享者：阿珍\u003c/p>\u003cp>上周，一个很好的朋友向我推荐投资理财产品，我其实没有这方面的需求。我就对她说：非常抱歉，我最近在世界各地旅游，开销比较大，我的家人最近做生意问我借了一笔钱急用，导致我现在也没有多余的钱投资这个产品。你的这个项目前景挺不错，希望你的项目越做越好。对方觉得我可能在敷衍她。\u003cbr>\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>通过前面的学习与讨论，相信大家都对拒绝他人要求，积极地说“不”有了更深刻的认识，，最后，请大家在便签上写下一周的时间内的一个具体的应用或者行动。&nbsp;希望大家能够写下具体的包括时间、地点、人物、内容、以及预期结果。限时为2min。\u003c/p>\u003cp>分享者：&nbsp;王蒙\u003c/p>\u003cp>接到朋友的活动邀请参加数据分析课程，最近我事情比较多，没有那么多的精力参加这个课程。今天学了“积极的拒绝”这个方法，下周一，我会这样回复她：\u003c/p>\u003cp>非常荣幸收到你的邀请。这个课程我已经期待很久了。（热情开场）\u003c/p>\u003cp>我们公司的业务最近几个月增长迅猛。有两个新项目是我主要负责的，我接下来的一个多月都会忙于搭建这些项目，尽最大的努力取得项目成功。（解释缘由）\u003c/p>\u003cp>为了集中精力工作，我不得不放弃很多事情，很遗憾，其中一件就是不能参加这次的课程。（表达遗憾）\u003c/p>\u003cp>如果七月份还有这个课程，请告知，我一定会参加。与此同时，祝你的课程开展顺利，取得丰硕成果（温情结尾）\u003c/p>\u003cp>预期结果是我拒绝了朋友这次的邀请，朋友理解并同意7月份开新课程再邀请我参加。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1557744753000,"updated_at":1557831145000,"ria":true},{"id":7573,"topic":"沟通效率","learn_goal":"学会如何积极地说“不”","remark":"","level":"TF1-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"流觞","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;自我介绍一下，我是流觞，我的职业是一名电信的工程师。平时喜欢读小说和心理管理类书籍，除此之外，最大的爱好是街舞。\u003c/p>\u003cp>今天带来的的书是《七堂思维成长课：精英群体的行为习惯》，作者是卡罗琳·韦布，作者在麦肯锡工作了12年，培训过无数新人，积累了大量实际案例和工作经验。作者把职场人士工作中可能应对的诸多麻烦，化简成七堂课，深度剖析了精英人群如何安排自己的生活，面对负面情绪，结交和管理人脉，最终打造属于自己的高质量生活。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11059,"quote":"\u003cp>我们谈到了每天的工作时间有限，所以你不可能所有事情都做。每次你对一个请求说“是”、实际上就在对其他事情说“不”。所以你的肯定回答一定要针对重要的、缺你不行的事情。但要集中时间和精力办事的一个普遍障碍是，我们都不想拒绝向我们提要求的那个人婉拒也很难说出口。“我不喜欢冲突，也不希望让别人失望，”安东尼说，“所以我觉得说‘不’很难，如果是不得不拒绝的情况，在打电话或走进会场前我都会精神紧张。”\u003c/p>\u003cp>这就是“积极地拒绝”这个办法的用武之地了。如果你发现自己很难从较低优先度的事情中抽身，那么学着如何积极地说“不”就像发现了新的超能力一一能让所有人对你做的决定如沐春风（包括你自己）。\u003c/p>\u003cp>为了提高成功拒绝的概率，你应该以积极而不是消极的信号开头，比如：\u003c/p>\u003cp>⒈热情开场。首先认可并且赞许对方的请求。\u003c/p>\u003cp>⒉你的“是”。然后，不要以“真的很抱歉……”开场，兴高采烈地突出你正在忙的积极的要紧事，解释为什么这件事有意思、很重要或者对你意义重大。最好找一个能和你的谈话对象产生共鸣的理由。\u003c/p>\u003cp>⒊你的“不”。解释清楚情況，表达遗憾之意，意思就是你无法答应他们的请求。\u003c/p>\u003cp>⒋温情结尾。也许你可以在不影响自己完成真正优先事项的前提下，给个建议或提供帮助，比如引荐能帮上忙的人。最不济也可以热情祝愿对方项目成功。这是一句很重要的结束语，而我们通常都光顾着不好意思拒绝别人，而忘了说这一句。\u003c/p>","explains":"\u003cp>求人帮忙和帮别人的忙是日常工作与生活中经常会遇到的事，然而有的忙我们不想帮，或者是实在帮不了的时候，拒绝向我们提要求的人，却又害怕把关系弄得很紧张。你希望通过婉拒期待对方能理解和支持，但人们听到发出消极信号的“真的很抱歉……”表达，还是会让对方高度戒备，你就很难获得理解。\u003c/p>\u003cp>这时，“积极的拒绝”是一种很好的表达方法。通过积极的语言信号开头表达，然后再深入表达自己想说的，最后表示遗憾之意和热情祝愿对方项目成功，能让所有人对你的决定表示认同。\u003c/p>\u003cp>具体的做法如下：\u003c/p>\u003cp>首先，热情的回应对方的请求；\u003c/p>\u003cp>第二，解释缘由，让对方认可自己正在处理工作重要性；\u003c/p>\u003cp>第三，表达遗憾无法答应对方的请求；\u003c/p>\u003cp>最后，热情祝愿对方项目成功。\u003c/p>\u003cp>在委婉拒绝的同时，主动加上替代方案，也会给人留下正面积极、想帮助对方解决问题的印象。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>先举一个我自己的例子：我前几天晚上到客户公司处理业务，当业务处理好的时候，公司又派来其他的业务，我这时就对客户说：“业务已经完成，你这边派人检查一遍，我还有其他事就先撤了。“客户提要求说必须等他们工程师检查完才能离开。等他们工程师检查完起码需要半个小时，我再次和客户沟通说：很抱歉，我这里确实有急事，等不了那么长时间。\u003cbr>\u003c/p>\u003cp>这样的表达还是无法获得客户的理解\u003c/p>\u003cp>运用拆页积极的拒绝如下：\u003c/p>\u003cp>首先，您提出的要求非常合理，我内心是赞成您的决定。\u003c/p>\u003cp>其次，您也清楚，现在是晚上，非法\u003c/p>\u003cp>定工作时间我们还在值班就是为了处理客户的业务中断等突发情况的发生，顾客满意是公司的一贯宗旨，高效及时处理故障是我们的职责所在。\u003c/p>\u003cp>现在，另一家用户业务出现问题，为了及时处理，我需要提前离开，请您谅解。\u003c/p>\u003cp>最后，如果您公司的工程师在检查过程中发现问题，您可以联系网管中心帮您查看。\u003c/p>\u003cp>希望您工作顺利，生活愉快。\u003c/p>\u003cp>请大家回想下自己在生活或者工作中，朋友或者同事向你提出难以接受的要求，你是如何回应的。你的回应是否令对方满意，请大家写在便签上，并在在小组内分享，限时2min。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>通过前面的学习与讨论，相信大家都对拒绝他人要求，积极地说“不”有了更深刻的认识，，最后，请大家在便签上写下一周的时间内的一个具体的应用或者行动。&nbsp;希望大家能够写下具体的包括时间、地点、人物、内容、以及预期结果。限时为2min。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554971380000,"updated_at":1557746777000,"ria":true},{"id":7484,"topic":"给大脑建立过滤机制","learn_goal":"完成过级TF2-4","remark":"通过给大脑设置过滤机制和心理对照，在使用积极心态的同时，去预想困难是什么，这样有更多的准备，从而更加顺利实现自己的目标","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"【自我介绍】各位伙伴大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新知识，共同进步。\r\n【学习目标】希望大家在学习完这个内容之后，当你再遇到重要事情的时候，不再是被事情推着走，而是可以使用给大脑建立过滤机制的方法，帮助自己设计出一个顺利完成任务的计划。\r\n【图示介绍】\r\n【F】今天我分享的内容来自《七堂思维成长课》这本书，它的作者是英国的卡罗琳.韦布。卡罗琳在全球知名的咨询管理公司——麦肯锡工作。大家都知道在麦肯锡女顾问不容易干到女合伙人更是难上加难，而卡洛琳完全是灭绝师太型的存在，她在麦肯锡供职12年，是全球仅有的1%的女性资深合伙人之一。在书中她深度剖析了精英人群是如何安排自己的生活，如何面对负面情绪以及如何结交和管理人脉的。\r\n【A】因为作者有过非常全面的麦肯锡训练的经历，而且她在麦肯锡也训练了无数的新人，所以同其他同类型的书相比，卡洛琳解读了大量精英人群的实际问题和这些问题的解决方案。而且本书的理论基础比同类的书也更为扎实，作者深入研究了行为科学、心理学和神经科学，研读了600多篇论文和专著，所有的精华都凝结在这本书里。\r\n【B】你是不是会为自己无法进入最近的工作的最佳状态而苦恼？你苦于自己不能成功影响他人而烦恼？本书作者在每个部分，对于职场人士都给出了精确的行动建议，可以帮助我们聚焦目标，提高执行力，扩大影响力，甚至还可以帮助发现自己的优势，教给我们打造属于自己的高质量的生活的方法。是每个上进青年非常好的床头书。\r\n【过渡】接下来我们进行一下分组，我们今天分为两组，我的左手边一组，右手边一组。\r\n下面请大家花两分钟的时间阅读一下原文，读完后的请示意我。","ratings_count":1,"texts":[{"id":11266,"quote":"\u003cp>我们无法掌控一切，但我们能够做到的是调整工作时间的感受，更用心地设置感知过滤机制。这时候每天坚持设定意图就很有用了，养成这个习惯能让我们留意自己每天的优先事项、关注的事和情绪。\u003c/p>\u003cp>我的办法如下，花一小段时间从三个角度来考虑(这三个角度的英文都以字母A开头，方便记忆) :\u003c/p>\u003cp>Ø&nbsp; 目标:想想今天活动中最重要的事项、要见的人以及要做的工作。要办成这些事最重要的是什么?那就是你的真实目标。\u003c/p>\u003cp>Ø&nbsp; 态度:下个工作日要来了，花时间留意并且正视那些支配你思维或情绪的你所关心的事。这些你所关心的事能帮你达成真实目标吗?如果不能，你能暂时把它们放在一边吗?\u003c/p>\u003cp>Ø&nbsp; 关注:从你实际的优先事项出发，你想把精力集中在哪儿?想清楚你想更多看到什么，然后确保自己按计划寻找。\u003c/p>\u003cp>我共事过的大部分人都认为，最好是在一天开 始前就弄清楚这些问题，可以是在早上或者前一天晚上。但因为这个日常习惯占用的时间不会超过一两分钟， 你从一个任务飞奔到下一一个任务之前再找时间设定意图也不晚。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段讲解的是在我们开始做一件事情，或者是在开始一天工作的时候给大脑建立过滤机制的办法。在这里我要解释一下大脑的过滤机制，大脑对于外部复杂的世界只能分配很有限的注意力。在一件事情发生的过程中，大脑就会优先处理他自认为重要的事情，同时把不太重要的事情过滤掉，比如当你集中精力看短信的时候，大脑就会忽略正在与你交谈的同事的话语，当你的同事提高音量，最终到达你的大脑时，你才会突然惊醒，反问道：啊？你刚才说话了？\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>也正是因为这种过滤机制，于是才有了哲学家的那句话：你只会看到你想看到的，而忽略了那些大脑中没有任何意识的事物，所以如果可以在每天，或者是每件事情开始之前，就在大脑中植入那些你更倾向于发生的事情，大脑就会在真实的世界里寻找与你植入的景象更为类似的细节，帮助发现更多的潜在可能性。\u003c/p>\u003cp>\u003cstrong>细化步骤【How】\u003c/strong>\u003c/p>\u003cp>那么我们给大脑建立过滤机制，从哪三个方面入手？呢？\u003c/p>\u003cp>\u003cstrong>第一个方面是目标，思考一下，对于你要去做的这件事情，你的目标是什么，请用自己的语言表达出来。\u003c/strong>\u003c/p>\u003cp>你要去做的事情，可能是你要去参加一个面试，也可能是公司会议的主持工作，也或者是你要去给你的朋友订一份礼物，不管这个事情是什么，请一定要清楚你的目标，并能通过语言表达出来。\u003c/p>\u003cp>\u003cstrong>第二个方面是态度，深呼吸，把自己调整到去做这件事情的最佳状态/态度\u003c/strong>\u003c/p>\u003cp>现在你已经有了目标，你觉得这件事情重要么？你应该以什么样的状态/态度面对这件事情呢？比如你要主持公司的庆功会，你的状态应该是什么样子的？精神饱满，神采奕奕，充满希望的状态。如果你主持的是公司重大项目总结反思会呢？如果是我，我的状态一定是严肃，认真，思考的状态。\u003c/p>\u003cp>\u003cstrong>第三个方面是你的关注的细节，设想一下，在这件事情进行的过程中，你会去关注哪写细节呢？\u003c/strong>\u003c/p>\u003cp>你如果要去做这件事情，你要关注哪些情况呢？这些也都需要你设想一下，比如，你要去参加一次面试，你会关注哪些细节？这就可以提前设想一下，比如，你可能更加关注面试官对你提出的问题，也可能你会更加关注面试官对你的态度举止。这些细节都会让你以更加认真的态度投入到面试中。\u003c/p>\u003cp>【\u003cstrong>可能的异议处理\u003c/strong>】\u003cbr>\u003c/p>\u003cp>或许有人会问这真的管用吗？只要在大脑中建立了过滤机制，事情就会朝我们想要的方向发展？这里需要说明的是：事情当然是因为人们的行为而改变的，给大脑设置过滤机制是给注意力提供了方向，大脑会优先注意到与过滤机制更类似的信息，而我们的行为就是受到这些信息所左右的。\u003c/p>","interaction":"\u003cp>【激活A1】\u003cbr>\u003c/p>\u003cp>现在请大家回忆一下，在你的过去的工作或者生活中，有没有发生过类似这样的事情——你被安排去做某件事情，你一听就觉得：天哪，怎么会给我安排这件事情呢，这事儿怎么能做好呢？但是没办法你只能去做，结果真的是按照你预想的样子，很糟糕。大家有印象发生过这样的事情么？\u003c/p>\u003cp>\u003cstrong>【分享者】\u003c/strong>\u003c/p>\u003cp>记得高三的时候，学校开大会，让我作为学习代表发言。当时没有过这样的经历，就很苦恼，觉得怎么会是我啊，我怎么能说好呢？我肯定做不好这件事情，这可怎么办啊？然后我就每天苦恼，也没有特别的准备，结果到了当天，让我发言的时候，果然是一塌糊涂，给我留下了很深刻的印象。\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>嗯，感谢我们这位小伙伴的分享。刚才看大家说的热火朝天，看来大家也都有过这样的经历，而且那件事情也给各位留下了非常深刻的印象，那么现在在请大家思考一下，此刻你已经学会了给大脑建立过滤机制的方法，三步：设目标，调状态，设想关注细节。\u003c/p>\u003cp>那么现在再给你一次机会，回到刚才你说的那个场景中，你用给大脑设立过滤机制的方法，你的目标会是什么呢？你会在大脑中设置什么样的过滤机制呢？每一步骤你会怎么做？我们讨论一下，一会我们会找小伙伴分享。\u003c/p>\u003cp>\u003cstrong>【分享者】\u003c/strong>\u003c/p>\u003cp>如果现在可以回去的话，我可能还会觉得诧异，怎么是我发言呢？然后我会去思考：我怎么样才能把这件事情做好，那我的目标肯定是：在大会上有一个比较优秀的表现。因为自己没有过这方面的经验，就会去练习。我会把抱怨的状态、调整到积极准备的状态。然后我回去思考我的一些学习习惯，比如老师为什么让我做学生代表啊，我有哪些学习的优点啊，我比他人好的地方是哪里啊？思考完之后，我会做一些整理，然后我会思考一下我在讲话的时候的一些关键细节，比如我那天应该穿什么衣服，什么样的一个表现，是不是要准备一个发言稿，做一些细节上的准备。\u003c/p>\u003cp>我想这样子会能帮助到我，如果有机会回到过去，就会表现的更好。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>感谢这位小伙伴的分享，这就是在大脑中建立过滤机制带来的好处，我们会调动一切的能力来促使事情发展得更加顺利。\u003c/p>\u003cp>那我们一起来回顾一下在刚才的第一个拆页中，我们讲的是针对某件事情，如果在大脑中用过滤机制把这件事情朝积极的方向过滤一遍，可能就会更好的帮助我们顺利完成这件事情。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>大家还记得这三个步骤是什么么？\u003c/p>\u003cp>\u003cstrong>【学习者回答】\u003c/strong>\u003c/p>\u003cp>学习者：设目标，调状态，设想关注细节。\u003c/p>\u003cp>非常感谢大家的反抗，看来大家都记得很清楚。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>在这三步骤中，大家觉得哪一步最难呢？\u003c/p>\u003cp>\u003cstrong>【学习者回答】\u003c/strong>\u003c/p>\u003cp>设置目标比较困难，因为有的时候会弄不清楚自己的目标到底是什么，很容易就忘记初心。\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>非常感谢各位伙伴的回答，是的，看来大家跟我想的是一样的：设置目标这个环节其实是很有难度的。\u003c/p>\u003cp>那我想问一下，大家有没有经历过这种情况，就是在设置目标的时候，总会有重重的障碍横在我们与目标之间。对于这些障碍，我们没有办法无视它，但又随时可能发生，大家遇到过这种情况么？\u003c/p>\u003cp>\u003cstrong>【学习这回答】\u003c/strong>\u003c/p>\u003cp>经常遇到\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>这时我们应该如何设置目标呢？需要注意哪些点呢？\u003c/p>\u003cp>接下来我们来看第二个片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":11267,"quote":"\u003cp>\u003cstrong>【R片段二】\u003c/strong>\u003c/p>\u003cp>不可思议的是，加强积极意图的一个很好的办法居然是稍微思考一下消极面。我指的是诚实的思考哪些因素可能阻碍你实现目标，然后你就能直面这些障碍。这个技巧被称为“心理对照”，顾名思义，就是将理想结果与烦人的日常生活进行对比。\u003c/p>\u003cp>这让人联想到商业书籍《从优秀到卓越》中提到的“斯托克代尔悖论”。这个悖论的名称取自美国海军中将詹姆斯斯托克代尔采用双面应对策略，它作为越南战俘熬过了八年艰难的岁月幸存下来，其间他身边的人，大多在绝望中走向灭亡，是德国戴尔认为不止悲观主义者，缺乏忍耐艰难处境的心理力量，盲目的乐观主义者也缺乏，因为他们要面对积极的信念落空后连绵不断的失望情绪，斯托克代尔这么说：“无论面对的是何种现实，你绝对不能把你终将获胜的信念——这点你绝对不能丢”\u003c/p>\u003cp>如今心理学家已经确认，这种现实的理想主义，只是确保我们将意图转变成行动的入场券，感谢上天，我们不用面对丈夫为存活下去，必须面临的那些恶劣挑战，但每天我们也会面对各种障碍，比如不成熟的技术手段，同时最后一分钟意想不到的请求等等。研究发现，人们如果在细心思考其想要的结果的同时，也仔细思索面临的障碍，并且做两手准备，那么他们达成目标的概率就会大增。研究发现，我们生活的很多方面都是如此，不论是职场事业，学业成绩还是恋爱关系。\u003c/p>\u003cp>为了每天在制定计划时通过心理对照获益，你可以问自己：\u003c/p>\u003cp>Ø&nbsp; 在你成功达成今天目标的路上，什么最可能成为障碍？\u003c/p>\u003cp>Ø&nbsp; 为防止出现障碍你的“如果…..那么”临时计划是什么？\u003c/p>\u003cp>就是“如果-那么”的办法最终帮我实现夙愿:早上开始工作前去散步。但我给早起散步还加了- -层保险，因为我知道恶劣天气(“啊，下雨了，我不用去了吧”)和热水澡的诱感(“我很快冲个澡....了，再去散步太迟了”)是我出门散步的重大潜在障碍。所以我加了几条“如果一那么”计划来应对:\u003c/p>\u003cp>Ø&nbsp; “如果我想去冲澡， 那么我就让自己穿上昨天的衣服，告诉自己不会碰到认识的人，还告诉自己散步后要好好冲个澡作为奖励。”\u003c/p>\u003cp>Ø&nbsp; “如果下雨， 那么我就穿上防水外套， 戴上帽子，这些都放在门边以方便拿取。”\u003c/p>\u003cp>这样小小的临时计划对确保你取得成功非常有效。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在学习完这个片段之后，希望你下次在设置目标的时候，能够预想到目标实现过程中可能出现的困难，并且把问题写下来再用，用“如果...那么...”的方法寻找到解决方法。\u003c/p>\u003cp>\u003cstrong>【原文讲解】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这一段文字告诉我们什么是心理对照，以及如何应用心理对照产生积极的效果。那么到底什么是心理对照呢？就是我们在思考一件事情的目标时，不仅要想到积极的方面，也要思考消极的方面，思考一下实现目标的过程中可能会遇到什么样的困难。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>我们不是魔法师，我们遇到的事情事情不会完全按照我们的设想的样子来发展，那么在设置目标的时候，不妨思考一下消极的地方，这样我们便可以提前一步想到应对困难的方法，有充足的时间预防突发事件，不会让自己措手不及。\u003c/p>\u003cp>\u003cstrong>细化步骤【How】\u003c/strong>\u003c/p>\u003cp>到底怎么做呢？\u003c/p>\u003cp>\u003cstrong>第一，仔细思考你的目标，把它写下来。\u003c/strong>\u003c/p>\u003cp>把你的目标写下来，能够帮助你更好的正视面对这个任务，\u003c/p>\u003cp>\u003cstrong>第二，思考达成目标的过程中可能出现的障碍。\u003c/strong>\u003c/p>\u003cp>在完成目标的过程中，如果我们能思考一下可能会出现什么样的困难，将会在什么时候发生，通过我们的准备，就可以避开、解决困难，顺利达成目标。\u003c/p>\u003cp>\u003cstrong>第三，用“如果...那样...”的方法来做好预备方案。\u003c/strong>\u003c/p>\u003cp>关于“如果...那样...”规则我们可以这样理解：如果发生了X的情况，那么我就采取Y行动。这一步是在未来可能发生的困难和采取行动之间搭建了一座桥梁，让我们更好的把握事情的走向。比如我和小溪沟通团队出游的事情，我的目标是让小溪同意现在的出游方案，问题点是：小溪可能不同意去很多同事选择的宁波。接下来是我的思考：如果在沟通过程中，小溪对出游地点有异议，那么我就拿旅行社给的报价给他，告诉他其实在这个季节，不管去哪里费用都差不多，如果小溪对出游的地点还是有意义，那么我会建议采用投票的方式解决这个问题。这就是“如果...那样...”的应用。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>“如果-那么”这个方法其实很好用，说一个我自己的经历：\u003c/p>\u003cp>周六的时候，我要打扫卫生，把家里打扫干净，同时，我还给“打扫卫生”加了一层保险，因为我知道朋友的邀请（嗨，Mona，今天天气这么好，我们一起去逛街）和 自己的懒惰（哎呀，明天再收拾吧，难得的清净，可以多休息会儿）是我收拾家务的重要敌人，所以，我加了几条“如果-那么”的计划来应对：\u003c/p>\u003cp>Ø&nbsp; 如果有朋友邀我出门，那么我就穿脏衣篓里的衣服出门，以此来刺激自己，一定要把家里的收拾干净。\u003c/p>\u003cp>&nbsp; Ø&nbsp;如果自己想偷懒，那么我就把家里的音响打开，让它想起劲爆的音乐，这样让自己的神经都精神起来，从而放弃昏昏沉沉想偷懒的想法。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>可能有人会说生活中这么做，太累了，以前我不这么做，也没有任何影响啊，\u003c/p>\u003cp>其实我们会发现，一般情况下，人们在做某件事情的时候，的确没有准备预案的习惯，所以呢，当障碍或者困难出现的时候，人们很多时候都会手足无措，开始抱怨；或者因为某些问题的发生，事情不能顺利发展，也因为没有预案，他们就孤注一掷，头撞南墙，结果导致计划失败，目标无法实现。所以我们在做事情的时候，最好还是要有预备方案，这样灵活变通，哪怕是走了曲线，也会帮助我们实现目标。\u003c/p>\u003cp>\u003cstrong>【可能出现的异议】\u003c/strong>\u003c/p>\u003cp>还有小伙伴会问，“如果...那么..”的情况经常发生，从小我们就用这个学习造句，这根本算不上是什么方法，最直接的，我们常说“如果他不同意，那么我们就不做了”。\u003c/p>\u003cp>在这里我需要去提醒大家的是“如果...那么...”这个方法是为你前面设置的目标而服务的，最终的目的是为了帮助目标的达成。而在现实生活中大家常说的“如果...那么...”已经改换了目标。\u003c/p>\u003cp>我们举个例子，比如今天中午你的目标是吃一碗面，按照片段中“如果...那么...”的方法应该说：“如果A饭馆没有油泼面，那么我就去B饭馆吃”，而实际生活中我们说的是：“如果没有油泼面，那我就吃炒米饭”，我们会发现目标已经改变了\u003c/p>","interaction":"\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003c/p>\u003cp>学习了“心理对照”以及“心理对照”的应用，下面我们来做一个案例研讨。小北是个单身男生，周围所有的亲戚朋友都觉得小伙能挣钱，脾气好，颜值高，纷纷为他的婚事着急，而小北对自己的状态很知足，觉得单不单身不重要，重要的是活得开心。他的母亲告诉他，有亲戚想给他介绍了对象，小北面对这种情况陷入了思考，\u003c/p>\u003cp>\u003cstrong>请各位伙伴思考一下，小北此刻他的目标是什么？\u003c/strong>如何应用“如果…..那么…..”来帮助自己实现目标\u003c/p>\u003cp>\u003cstrong>【分享者】\u003c/strong>\u003c/p>\u003cp>我们觉得小北的目标是：更开心的生活。\u003c/p>\u003cp>小北的父母想让他去相亲，如果他不去的话，父母就会一直跟他唠叨，那么为了避免父母的唠叨让自己不开心，那么小北就去相亲，如果相亲见到的女孩比较符合小北的心思，那么小北就可以选择接触一下，聊一聊，万一真的很合适呢？如果相亲见到的女孩没有那么合心意，那么就拒绝，回去告诉父母今天这个不太合适。如果父母还给介绍，那么就再去见面。\u003c/p>\u003cp>总体来说小北的目标就是开心的生活。父母不唠叨他，他会开心；有合适的人，那就试一试会开心，那就试一试；没有合适的人，拒绝会开心，那就拒绝。\u003c/p>\u003cp>\u003cstrong>【A2应用催化】\u003c/strong>\u003cbr>\u003c/p>\u003cp>非常感谢小伙伴的分享，我想这样小北应该就可以放松了。\u003c/p>\u003cp>接下来请大家想一想自己在未来的一周或者是一个月之内，会不会遇到这样的场景：\u003c/p>\u003cp>在你和家人的沟通过程中，家人可能会否定你的想法；\u003c/p>\u003cp>在工作中，可能会有同事拒绝你的请求；\u003c/p>\u003cp>或者是当你在和朋友一起的时候，朋友会不同意你的决定；\u003c/p>\u003cp>你会遇到什么样的场景呢？\u003c/p>\u003cp>\u003cstrong>【分享者】\u003c/strong>\u003c/p>\u003cp>我会在工作中，与合作伙伴遇到一些问题\u003cbr>\u003c/p>\u003cp>\u003cstrong>【问题】\u003c/strong>\u003c/p>\u003cp>在这个过程中你的目标可能是什么？会出现哪些障碍？请你用“如果...那么...”的方法解决问题。\u003c/p>\u003cp>\u003cstrong>【分享者】\u003c/strong>\u003c/p>\u003cp>我是做研发的，我们现在要研发一种产品，我的目标就是在规定的时间范围内把这个产品交给需求方。因为我们自己研发出来之后，生产成本更低利润更大，对后期扩大规模也有帮助。\u003c/p>\u003cp>可能的障碍：我自己研发的过程中，可能会出现原料，或者是工艺方面的问题，导致这个产品可能在规定时间内容研发出不来，或者不是100%合格\u003c/p>\u003cp>方案：如果我自己无法完成，那么我就暂时直接采购成品给到需求方。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>非常感谢小伙伴的分享，希望这个方法可以帮助到大家。也非常感谢大家的积极参与。\u003c/p>\u003cp>今天我们首先学习了通过进行大脑的过滤机制的设置这个方法，使我们顺利获得了自己想要的结果。然后我们学习的是通过“心理对照”的学习，促使我们在积极心态的同时去预想困难是什么，再用“如果..那么..”的方法来克服，这样面对困难，我们就会有更多的准备，从而更顺利的实现自己的目标。\u003c/p>\u003cp>相信这些方法一定可以在实际生活中帮助到我们，促使我们升职加薪，当上总经理出任CEO，迎娶白富美，走上人生巅峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1553678230000,"updated_at":1553678230000,"ria":true},{"id":7174,"topic":"如何拒绝他人","learn_goal":"成功过级3-1","remark":"很难拒绝他人么？每次都需要勇气？今天教你四步提高自己成功拒绝他人的几率","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>【学习目标】希望大家在学习了今天的内容之后，可以使用“积极拒绝”的方法，帮助自己改善日常生活中不能成功拒绝他人的情况。&nbsp;\u003c/p>\u003cp>【自我介绍】大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新的知识，共同成长。&nbsp;\u003c/p>\u003cp>【图示介绍】&nbsp;\u003c/p>\u003cp>（事件场景）请大家跟我来一起想象这样一个场景：最近你的工作特别忙，各种总结、报告，可能周末都休息不了了，这时办公室老张过来，递了一沓资料，对你说：这报告非常着急，而且这活儿，我手下的人弄不了，就你能干得了，两天时间行吧，周五给我成品。你认真思考了一下，非常真诚的看着他，说：张儿，真对不起，我手头一大堆工作，这个报告我没时间弄了。你发现老张显然不高兴了，最后，老张“哼”了一句，翻了个白眼撇撇嘴走了。\u003c/p>\u003cp>&nbsp;（提问）这是不是你工作境遇的真实写照？你平时会直接拒绝他人么？对于自己的拒绝他人的方式，你感到满意吗？有没有更好的拒绝他人的方法呢？&nbsp;\u003c/p>\u003cp>（影响）我们知道，在生活中如果对他人的事情说‘Yes’，那么我们只能对自己的事情说‘No’，所以为了保证自己更多的时间和精力，我们不得不拒绝他人，但在拒绝的背后，可能会隐藏着很多的问题，小的拒绝可能只是当场比较尴尬，而某些事情的拒绝，就可能会使你失去一个伙伴，甚至一份工作。&nbsp;\u003c/p>\u003cp>（解决）给予他人帮助，当然是一种美德，但你难免会有拒绝他人的时刻，那有什么好的方法，不仅可以提高成功拒绝他人的几率，还能让他人更容易接受呢？今天我们就来解开这个谜题。\r\n今天的内容来自于《七堂思维成长课》，这是一本非常好的职业人士的床头书，它可以帮助我们聚焦工作目标，提高执行力，扩大影响，发现自己的优势。&nbsp;\u003c/p>\u003cp>【过渡】接下来我们来分一下组啊，今天人不多，我们就是一组，\r\n下面呢，请大家花两分钟的时间来阅读一下原文，看完的伙伴请示意我。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":10582,"quote":"\u003cp>什么是积极的拒绝\u003c/p>\u003cp>现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自两像这件事..听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进人了防守模式:“你要退出!出现威胁!”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003c/p>\u003cp>安东尼讲了他最近一个例子，他用积极的拒绝做好了工作安排，他工作中特别耗时间的一项任务是远途出差，他经常答应出差去半有意思，但并不要紧的事，最近她答应了去吉隆坡出差，后来才意识到要腾出时间出差有多困难。他觉得没办法推掉出差计划，但去出差情形更槽，那意味着他只能马马虎虎完成项目工作，但项目对公司的未来至关重要。最终，他意识到自己不得不通知组织者推掉出差这样才能在日程上腾出足够的时间。\u003c/p>\u003cp>正常情况下安东尼可能会这么写:\u003c/p>\u003cp>“非常抱歉，很不巧我没办法和你一起出差去吉隆坡了。我们最近接了三个大项目，我发现项目工作太多，忙得人不可开交。所以尽管我多方努力，实在腾不出时间出差。再次深表歉意。”\u003c/p>\u003cp>与之相对，安东尼做出的积极的拒绝如下:\u003c/p>\u003cp>“非常荣幸收到你的邀请去吉隆坡。你手头的工作真是既了不起又吸引人。如你所知，我们这边的业务最近几个月也增长迅猛。我们接下来三个让人振奋的新项目，能真正让客户改变对营销的看法。我未来几个月都会忙于搭建这些项目，不负众望取得项目成功是我的职责所在。但是，为了全力工作，我不得不放弃很多事情，很遗憾，其中一件就是不能和你共赴吉隆坡。我此前非常期待这次出行，所以现在也很失落。如果我能帮忙联系到取代我的人，为出差团队贡献价值，请告知-我心里也有些人选。 与此同时，祝你旅行一切顺利， 取得丰硕成果。”\u003c/p>","explains":"\u003cp>我看各位伙伴都已经看完了片段，\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这个片段告诉我们什么是&quot;积极拒绝&quot;，其实理解起来并不难，&quot;积极拒绝&quot;就是用对方能够接受的方式拒绝他人。这种方式不会让对方消极的情绪，也不会因为我们的拒绝而产生敌意。\u003c/p>\u003cp>\u003cstrong>【概念对比】\u003c/strong>\u003c/p>\u003cp>也许讲到这里你仍然对积极的拒绝没有特别的印象，我们来举两个例子来理解一下什么是积极的拒绝，什么不是积极的拒绝\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>小新拒绝小丸子一起去看复联3，如果小新直接说“真对不起，我没时间陪你，我还有两套卷子没做完呢，”这算是积极的拒绝么？\u003c/p>\u003cp>学习者：不算\u003c/p>\u003cp>是的，这不算是积极的拒绝，因为积极的拒绝会考虑到对方的感受，绝不会在一开始就直接说“对不起”，直接表达“不”的意思。\u003c/p>\u003cp>\u003cstrong>【反例】\u003c/strong>\u003c/p>\u003cp>再比如：派大星受伤了，让海绵宝宝去买饭，海绵宝宝不想去，就说：我也饿了，阳光挺好，出去买饭去也行，给我一百块钱，我就去。”派大星没有一百块，于是只好作罢。这算是积极的拒绝么？\u003c/p>\u003cp>学习者：不算\u003c/p>\u003cp>是的，这当然也不是，这是以他人满足不了的条件做要挟，当别人满足不了的时候，只能作罢。这种做法只会让对方觉得你在无理取闹，更会觉得你不体谅他人。\u003c/p>\u003cp>\u003cstrong>【正例】\u003c/strong>\u003c/p>\u003cp>那什么是积极的拒绝呢？就拿小新拒绝小丸子一起去看复联3的邀请来说，如果小新回答的是：“去看《复联3》？真是太令人兴奋了，我自己就是漫威的超级影迷。你也知道，我马上就要期末考试了，今天我还有两套卷子都没有做完呢。所以真是抱歉，我今天没有时间陪你一起去看电影。这部电影这么精彩，祝你看的开心。”你看，小新的拒绝中，有积极的开场，也说了他要去做的事情，表达了拒绝的同时，也有温情的结尾，这就是积极的拒绝。\u003c/p>\u003cp>接下来我们一起来总体回顾一下这个片段的内容。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>让我们回想一下你在拒绝他人的时候，你会怎么说呢？直接说“不”么？因为这事最高效的方法，比如我们会说“对不起，我没时间”或者说“我觉得不行”。\u003c/p>\u003cp>这种方法虽然高效，却不利于当事人关系融洽。即使你已经很礼貌的对他人表示歉意，说明拒绝的理由，也觉得自己已经很真诚了，但“不能”“不行”“没时间”，这种带有否定意味的词语，它表示你对此事丝毫不感兴趣，你不接受这件事情，不认可对方的行为，所以不管你拒绝的理由是多么的充足，对方也很难理解你。\u003c/p>\u003cp>\u003cstrong>【How\u003c/strong>\u003cstrong>】\u003c/strong>那么我们到底怎么做才是“积极的拒绝”拒绝他人呢？\u003c/p>\u003cp>\u003cstrong>首先我们应该热情的开场，认可并且赞美对方的请求。\u003c/strong>\u003c/p>\u003cp>你可以称赞对方请求的事情很有趣，或者很锻炼人等等。以积极而不是消极的信号开头，可以提高成功拒绝的概率。\u003c/p>\u003cp>\u003cstrong>第二步说明你正在做的事情。\u003c/strong>\u003c/p>\u003cp>当然请不要以“但是”开场，你可以说“同时”这个词语。你用以轻松的、明确的语气告诉对方你正在积极准备的要紧事，解释一下这件事情的重要性、重大意义，或者是有趣的原因，最好这个理由也是对方认同的。\u003c/p>\u003cp>\u003cstrong>第三步表达你的拒绝。\u003c/strong>\u003c/p>\u003cp>在说明情况之后表达你的遗憾之情，也就是告诉他你无法答应他的请求。\u003c/p>\u003cp>\u003cstrong>最后是温情的结尾。\u003c/strong>\u003c/p>\u003cp>温情体现在表达你的关心，如你可以在回复的时候说“我没有时间，不过可以向你推荐一个能办这事儿的人”，或者说“我可能做不到你的要求，但我希望我能帮到你，不如你可以试试这个方法&quot;，此时你的关心，会让对方感觉到你的真诚，促使对方更理解你。最不行我们还可以热情的祝福对方顺利完成任务，取得成功。这种祝福是很重要的结束语，因为我们平时总是在忙着表达自己的歉意，而忘记了表达对成功的祝福。\u003c/p>\u003cp>\u003cbr>\u003cstrong>【互动提问】\u003c/strong>就是通过这么简单的四步，可以帮助我们提高成功拒绝他人的几率，那么大家来试想一下，这其中哪一部最难，你最容易忽略的是哪一部呢？\u003c/p>\u003cp>\u003cstrong>【学员回答】\u003c/strong>热情的开场，并且赞美对方的请求是比较难的，因为自己很难在当下就转换角色，意识到我们要热情，而且还能赞美对方的请求。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有的伙伴说，在温情的结尾时候，为了让别人更容易接受，我就为他提供一个能办这件事情的人吧。在这里想说明一下，如果你确定这个人合适，或者是与对方有交情，可以提议让他们去沟通，不要替别人允诺什么行为，以避免后期不必要的误会。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>也有伙伴会问，在生活和工作中，只要是我想要拒绝的，都可以用这个方法吧？那在这里说明的是，你作为当事人要清楚，有些事情是你的责任范围内的，是不可以拒绝的，比如你作为学生，因为心情不好，而拒绝写作业，这就是不能拒绝的情况。而有些事情，你并没有确定的责任，而是别人一厢情愿要求你的，比如你这个月是销售冠军，同事们就要求你请客，如果你不喜欢就可以用积极拒绝的方法，拒绝他人。但需要注意的是，并不是使用了这种拒绝的方法，你就一定能够成功的拒绝他人，我们知道这种方法是帮助提高成功拒绝的几率。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那现在我们已经学习完了积极拒绝的方法，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那最近各位伙伴有没有接到什么样的邀请是你想要去拒绝的呢？比如同事邀请你跟他一起出差，但是你手头有一堆的工作要处理？再比如闺蜜让你照顾她因为去旅游而无法照顾的狗狗，但是你婆婆在你家，她对狗狗毛过敏？再或者是你的爱人让你陪她一起去出席同学会，而你却并不感兴趣？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来我们尝试编一个小故事，或者是小剧本，就把你要觉得的这些事情设计出时间，地点，人物，事件起因、经过、结果，和当时双方的对话。请在其中用到\u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>积极的拒绝方法\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>这个技巧。我这里给到大家一个模板，大家可以参照一下，时间是五分钟，五分钟之后，我们请小伙伴分享一下。\u003c/strong>\u003c/p>\u003cp>【模板】\u003c/p>\u003cp>时间：周五下午&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 地点：办公室&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 人物：梅长苏、靖王\u003c/p>\u003cp>起因：靖王想约梅长苏周末陪他去健身&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 经过：靖王像梅长苏发出邀请，而梅长苏准备周末参加拆书活动过级\u003c/p>\u003cp>结果：梅长苏拒绝了靖王\u003c/p>\u003cp>\u003cstrong>对话：\u003c/strong>\u003c/p>\u003cp>靖王：长苏，周末跟我去健身啊，健身教练都约好了，还有一节游泳课呢，周日早上10点我去接你。\u003c/p>\u003cp>梅长苏：去健身啊，真是休闲的好项目，还能去游泳，这个活动真是挺适合我的，谢谢你这个运动健将，常常督促我健身，我这体质，健身对我还真是好处多多。对了，你还记得我跟你说的拆书帮么？\u003c/p>\u003cp>靖王：拆书帮？哦~哦~哦哦，就是你经常去参加活动的那个？你不是还立志要做拆书家呢？\u003c/p>\u003cp>梅长苏：是的，我现在都开始过三级了，就快成为三级拆书家了，我们这个活动每周一次，这周正好是安排在了周日，所以，周末健身这事儿我就不陪你去了。这样，誉王这周工作调整，不出差了，他有空，要不我帮你约一下他？\u003c/p>\u003cp>靖王：这样啊，我还说游泳完了去吃火锅呢，那算了吧，我去约誉王\u003c/p>\u003cp>梅长苏：好，工作一周了，你们玩的开心点啊~\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>时间：周二晚上&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 地点：小H下班的路上&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 人物：小H、读书会组织者小W\u003c/p>\u003cp>起因：临近年底，读书会组织合唱晚会，小W找小H去参加&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>经过：因为拆书过级的准备工作，小H周末没有时间\u003c/p>\u003cp>结果：小H拒绝了小W的邀请\u003c/p>\u003cp>对话：\u003c/p>\u003cp>小W：小H，咱们读书会打算年前做一个合唱晚会，我们分了5个小组，以组为单位比赛，你周末有空吧，咱们就在活动室组织组织，练习一下。\u003c/p>\u003cp>小H：合唱晚会？年前还有集体的活动呢？真不错，有机会跟大家聚一聚，还能一展歌喉，一定有很多人响应，这么一说还真挺期待的。对了，你还记得我跟你说的拆书帮么？当时，你还跟我说也要加入呢~\u003c/p>\u003cp>小W：记得啊，年底，我最近太忙了，都没有怎么去参加你们的活动。\u003c/p>\u003cp>小H：你确实是太忙了。我正在过级呢，你知道我是培训工作，这种练习对我的帮助很大，想着年前抓紧时间把逐字稿完成， 所以最近这几个周末我都腾不出时间了，真是遗憾，我参与不了。不过我相信，这次晚会你们这么早就准备，肯定安排的特别好好，一定会很成功的~\u003c/p>\u003cp>小W：你这是拼了的劲头啊，好吧，那我再去看看其他人有空么，也祝你顺利过级。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>非常感谢大家的分享。今天通过四个步骤的学习，大家对积极拒绝的方法有了认知和了解，并且也掌握了积极拒绝的步骤，希望大家在日常生活中可以去应用它，最终来改善自己在日常生活中不能成功拒绝他人的苦恼问题。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1548835358000,"updated_at":1550644340000,"ria":true},{"id":6644,"topic":"如何通过建立大脑过滤机制帮助我们完成任务","learn_goal":"成功通过TF2-4级别","remark":"一本很好的上进青年的床头书，帮助我们焦距目标，提高执行力，扩大影响力，发现自己的优势。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"【自我介绍】各位伙伴大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新知识，共同进步。\r\n【学习目标】希望大家在学习完这个内容之后，当你再遇到重要事情的时候，不再是被事情推着走，而是可以使用给大脑建立过滤机制的方法，帮助自己设计出一个顺利完成任务的计划。\r\n【F特征】今天我分享的内容来自《七堂思维成长课》这本书，它的作者是英国的卡罗琳.韦布。卡罗琳在全球知名的咨询管理公司——麦肯锡工作。大家都知道在麦肯锡女顾问不容易干到女合伙人更是难上加难，而卡洛琳完全是灭绝师太型的存在，她在麦肯锡供职12年，是全球仅有的1%的女性资深合伙人之一。在书中她深度剖析了精英人群是如何安排自己的生活，如何面对负面情绪以及如何结交和管理人脉的。\r\n【A优势】因为作者有过非常全面的麦肯锡训练的经历，而且她在麦肯锡也训练了无数的新人，所以同其他同类型的书相比，卡洛琳解读了大量精英人群的实际问题和这些问题的解决方案。而且本书的理论基础比同类的书也更为扎实，作者深入研究了行为科学、心理学和神经科学，研读了600多篇论文和专著，所有的精华都凝结在这本书里。\r\n【B利益】作者在每个部分都给出了精确的行动建议，可以帮助我们聚焦目标，提高执行力，扩大影响力，甚至还可以帮助发现自己的优势，教给我们打造属于自己的高质量的生活的方法。是每个上进青年非常好的床头书。\r\n【过渡】接下来我们进行一下分组，我们今天分为两组，我的左手边一组，右手边一组。\r\n下面请大家花两分钟的时间阅读一下原文，读完后的请示意我。","ratings_count":1,"texts":[{"id":9979,"quote":"\u003cp>我们无法掌控一切，但我们能够做到的是调整工作时间的感受，更用心地设置感知过滤机制。这时候每天坚持设定意图就很有用了，养成这个习惯能让我们留意自己每天的优先事项、关注的事和情绪。\u003c/p>\u003cp>我的办法如下，花一小段时间从三个角度来考虑(这三个角度的英文都以字母A开头，方便记忆) :\u003c/p>\u003cp>Ø&nbsp; 目标(Aim):想想今天活动中最重要的事项、要见的人，以及要做的工作。要办成这些事最重要的是什么?那就是你的真实目标。\u003c/p>\u003cp>Ø&nbsp; 态度( Attitude):下个工作日要来了，花时间留意并且正视那些支配你思维或情绪的你所关心的事。这些你所关心的事能帮你达成真实目标吗?如果不能，你能暂时把它们放在一边吗?\u003c/p>\u003cp>Ø&nbsp; 关注( Attention):从你实际的优先事项出发，你想把精力集中在哪儿?想清楚你想更多看到什么，然后确保自己按计划寻找。\u003c/p>\u003cp>我共事过的大部分人都认为，最好是在一天开 始前就弄清楚这些问题，可以是在早上或者前一天晚上。但因为这个日常习惯占用的时间不会超过一两分钟， 你从一个任务飞奔到下一一个任务之前再找时间设定意图也不晚。\u003c/p>","explains":"\u003cp>\u003cp>【I片段-原文讲解】\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>：这个片段讲解的是在我们开始做一件事情，或者是在开始一天工作的时候给大脑建立过滤机制的办法。在这里我要解释一下大脑的过滤机制，大脑对于外部复杂的世界只能分配很有限的注意力。在一件事情发生的过程中，大脑就会优先处理他自认为重要的事情，同时把不太重要的事情过滤掉，比如当你集中精力看短信的时候，大脑就会忽略正在与你交谈的同事的话语，当你的同事提高音量，最终到达你的大脑时，你才会突然惊醒，反问道：啊？你刚才说话了？\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>：也正是因为这种过滤机制，于是才有了哲学家的那句话：你只会看到你想看到的，而忽略了那些大脑中没有任何意识的事物，所以如果可以在每天，或者是每件事情开始之前，就在大脑中植入那些你更倾向于发生的事情，大脑就会在真实的世界里寻找与你植入的景象更为类似的细节，帮助发现更多的潜在可能性。\u003c/p>\u003cp>\u003cstrong>How：【细化步骤】\u003c/strong>\u003c/p>\u003cp>那么我们怎样才能建立起大脑的过滤机制呢？\u003c/p>\u003cp>\u003cstrong>首先，做一个自己能够随时看得到的提示，提示自己大脑是存在这种过滤机制的。\u003c/strong>\u003c/p>\u003cp>虽然你理解了什么是过滤机制，可是一忙起来，我们会轻易的忘掉它的存在，所以我们要有意识的去提示自己，比如你想要拥有美好的一天，那么你就可以把叫醒自己的闹铃，命名为：美好的一天开始了。然后大脑就会想象今天一切顺利的景象。\u003c/p>\u003cp>\u003cstrong>第二，在一天开始之前，或者是进行一项重要的事情之前，把你的目标写下来。\u003c/strong>\u003c/p>\u003cp>到底要去完成什么事情呢？是去见一个人，还是要把工作完成到什么进度。把这个目标写下来，不仅是因为这个目标很重要，而且会通过“写”这个动作让目标更加深刻。比如你今天要去辅导小A了解产品知识，此时领导让你去汇报项目进展，很有可能在你汇报之后，就忘记了辅导的工作。而假使早上你写下了这个目标，印象会更加深刻，在汇报的时候，你就可能会想起小A也参加了这个项目，接着就会由小A联想起今天你还要去辅导小A的产品知识。\u003c/p>\u003cp>\u003cstrong>第三，想象一下你在事情进展的过程中是什么样的心情，然后深呼吸，把当时你的状态描述给自己听。\u003c/strong>\u003c/p>\u003cp>我们之所以要进行预想，是因为这时你植入的感觉就是导火索，它会在你行动过程中寻找与你所想像的状态相同的感觉。而且我们听到自己的描述时，就会加强代入感。比如你预想辅导会进行的很顺利，你可以这样描绘自己的状态：在辅导的时候我和小A的状态都很好，虽然小A有一些问题，但思路是正确的，我们对存在的问题做了讨论和确认，小A很认真，我也很开心。当你听到这些话，就好像这个事情已经发生了，大脑就会寻找现实中进展得顺利的蛛丝马迹。而如果你忽略了这件事情，并没有预想事情的状态，如果小A遇到不懂的地方，或许你就会感到很烦躁，不明白为什么这么简单的问题，他居然就是不懂，于是你也很可能会感受到不愉快。\u003c/p>\u003cp>\u003cstrong>第四，从你期待的角度出发，把注意力集中在与你预想一致的细节上。\u003c/strong>\u003c/p>\u003cp>如果你给大脑设置了积极的过滤机制，关注点很可能就会停留在更加积极的地方。比如你在辅导过程中，小A对某个问题很纠结，如果你的关注点是积极的，你会认为他很认真，做事仔细是值得培养的人，但如果你的过滤机制中没有积极的点，或者你就没有设置过滤机制，你看到小A纠结在一个内容上，你就可能会认为他认死理儿，固执，由此会产生消极的感觉。\u003c/p>\u003cp>\u003cstrong>【可能的异议处理】\u003c/strong>\u003c/p>\u003cp>或许有人会问这真的管用吗？只要在大脑中建立了过滤机制，事情就会朝我们想要的方向发展？这里需要说明的是：事情当然是因为人们的行为而改变的，给大脑设置过滤机制是给注意力提供了方向，大脑会优先注意到与过滤机制更类似的信息，而我们的行为就是受到这些信息所左右的。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>\u003c/p>\u003cp>现在请大家回忆一下，在你的工作或者生活中，有没有发生过这样的事情呢？你被安排去做某件事情，你一听就觉得：天哪，怎么会给我安排这件事情呢，这事儿怎么能做好呢？但是没办法你只能去做，结果真的是按照你预想的样子，很糟糕。大家有印象发生过这样的事情么？\u003c/p>\u003cp>\u003cstrong>【学习者回答】\u003c/strong>\u003c/p>\u003cp>我每次出差去给经销商促销的时候，就会这样，一想就头大，觉得这次又要出去，哎呀，我要是做的最少怎么办？我能做好么？比较自我怀疑的那种，感觉每次去都无法发挥自己的价值。\u003c/p>\u003cp>\u003cstrong>【A2催化】\u003c/strong>\u003c/p>\u003cp>嗯，看来大家真的都有过这样的经历，而且那件事情也给各位留下了非常深刻的印象，那么现在在请大家思考一下，此刻你已经学会了给大脑建立过滤机制的方法，四步：包括做提示，写目标，描述状态，关注与目标一致的点。\u003c/p>\u003cp>那么在近期的未来，是不是还有与刚才你所想到的事情类似的情况发生呢？到时候你要怎样利用这个方法来为自己顺利完成这个工作，来做计划呢？每一步骤你会怎么做呢？我们讨论一下，一会我们会找小伙伴分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>我下周还要去出差，下县给经销店去做促销，我觉得如果要给大脑做一个过滤机制的话，首先，做一个提示，我可以在自己的座位写上：“帮助促销，实现价值，我可以”这几个字，让我每次出差的时候，都建立起信心。\u003c/p>\u003cp>第二，我的目标写成：帮助处理库存，销售目标6000人民币。\u003c/p>\u003cp>第三，我的状态，我描述一下：我微笑的看着顾客选购产品，在他们需要的时候，我适时的提供帮助，把自己熟悉的产品知识都介绍给她。我的旁边放着某些产品的库存，我会一一向顾客询问是否有需要这种产品。顾客对我的介绍很满意，他们向我点头，也向我微笑。我们彼此都很开心。\u003c/p>\u003cp>第四，我的关注点，首先我会放在顾客的反馈上，他们对我微笑，或者与我亲切的交谈，这些都是我应该注意到的，同时我还会把关注点放在产品的数量上，处理库存或者销售6000，我完成一样都是我实现价值的体现。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>\u003c/p>\u003cp>感谢这位小伙伴的分享，这就是在大脑中建立过滤机制带来的好处，我们会调动一切的能力来促使事情发展得更加顺利。希望你下周出差顺利~\u003c/p>\u003cp>我们发现建立过滤机制这四个步骤紧密相连，就像刚才分享的小伙伴，他的目标明确了，后面才会随之行动起来，而所有的努力都是为了达成这个目标。\u003c/p>\u003cp>那么在设置目标的时候，是不是也有需要注意的点呢？接下来我们来看第二个片段。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在学习完这个片段之后，希望你下次在设置目标的时候，能够预想到目标实现过程中可能出现的困难，并且把问题写下来再用，用“如果...那么...”的方法寻找到解决方法。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":9981,"quote":"\u003cp>不可思议的是，加强积极意图的一个很好的办法居然是稍微思考一下消极面。我指的是诚实的思考哪些因素可能阻碍你实现目标，然后你就能直面这些障碍。这个技巧被称为“心理对照”，顾名思义，就是将理想结果与烦人的日常生活进行对比。\u003c/p>\u003cp>这让人联想到商业书籍《从优秀到卓越》中提到的“斯托克代尔悖论”。这个悖论的名称取自美国海军中将詹姆斯斯托克代尔采用双面应对策略，它作为越南战俘熬过了八年艰难的岁月幸存下来，其间他身边的人，大多在绝望中走向灭亡，是德国戴尔认为不止悲观主义者，缺乏忍耐艰难处境的心理力量，盲目的乐观主义者也缺乏，因为他们要面对积极的信念落空后连绵不断的失望情绪，斯托克代尔这么说：“无论面对的是何种现实，你绝对不能把你终将获胜的信念——这点你绝对不能丢”\u003c/p>\u003cp>如今心理学家已经确认，这种现实的理想主义，只是确保我们将意图转变成行动的入场券，感谢上天，我们不用面对丈夫为存活下去，必须面临的那些恶劣挑战，但每天我们也会面对各种障碍，比如不成熟的技术手段，同时最后一分钟意想不到的请求等等。研究发现，人们如果在细心思考其想要的结果的同时，也仔细思索面临的障碍，并且做两手准备，那么他们达成目标的概率就会大增。研究发现，我们生活的很多方面都是如此，不论是职场事业，学业成绩还是恋爱关系。\u003c/p>\u003cp>为了每天在制定计划时通过心理对照获益，你可以问自己：\u003c/p>\u003cp>Ø&nbsp; 在你成功达成今天目标的路上，什么最可能成为障碍？\u003c/p>\u003cp>Ø&nbsp; 为防止出现障碍你的“如果…..那么”临时计划是什么？\u003c/p>\u003cp>就是“如果-那么”的办法最终帮我实现夙愿:早上开始工作前去散步。但我给早起散步还加了- -层保险，因为我知道恶劣天气(“啊，下雨了，我不用去了吧”)和热水澡的诱感(“我很快冲个澡....了，再去散步太迟了”)是我出门散步的重大潜在障碍。所以我加了几条“如果一那么”计划来应对:\u003c/p>\u003cp>Ø&nbsp; “如果我想去冲澡， 那么我就让自己穿上昨天的衣服，告诉自己不会碰到认识的人，还告诉自己散步后要好好冲个澡作为奖励。”\u003c/p>\u003cp>Ø&nbsp; “如果下雨， 那么我就穿上防水外套， 戴上帽子，这些都放在门边以方便拿取。”\u003c/p>\u003cp>这样小小的临时计划对确保你取得成功非常有效。\u003c/p>","explains":"\u003cp>\u003cp>\u003cstrong>【I片段：原文讲解】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>这一段文字告诉我们什么是心理对照，以及如何应用心理对照产生积极的效果。那么到底什么是心理对照呢？就是我们在看待问题的时候，不仅要想到积极的方面，也要思考消极的方面，思考可能会遇到什么样的困难。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>当我们想要给大脑建立过滤机制的时候，我们不能只想好的方面，因为我们不是魔法师，事情不会完全按照我们的意图来，那么在设置目标的时候，不妨思考一下消极的地方，这样我们便可以提前一步想到应对困难的方法，有充足的时间预防突发事件，不会让自己措手不及。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>到底怎么做呢？\u003c/p>\u003cp>\u003cstrong>第一，仔细思考你的目标，把它写下来。\u003c/strong>\u003c/p>\u003cp>把你的目标写下来，能够帮助你更好的正视面对这个任务，\u003c/p>\u003cp>\u003cstrong>第二，思考达成目标的过程中可能出现的障碍。\u003c/strong>\u003c/p>\u003cp>在完成目标的过程中，如果我们能思考一下可能会出现什么样的困难，将会在什么时候发生，通过我们的准备，就可以避开、解决困难，顺利达成目标。\u003c/p>\u003cp>\u003cstrong>第三，用“如果...那样...”的方法来做好预案。\u003c/strong>\u003c/p>\u003cp>关于“如果...那样...”规则我们可以这样理解：如果发生了X的情况，那么我就采取Y行动。这一步是在未来可能发生的困难和采取行动之间搭建了一座桥梁，让我们更好的把握事情的走向。比如我和小溪沟通团队出游的事情，我的目标是让小溪同意现在的出游方案，问题点是：小溪可能不同意去很多同事选择的宁波。接下来是我的思考：如果在沟通过程中，小溪对出游地点有异议，那么我就拿旅行社给的报价给他，告诉他其实在这个季节，不管去哪里费用都差不多，如果小溪对出游的地点还是有意义，那么我会建议采用投票的方式解决这个问题。这就是“如果...那样...”的应用。\u003c/p>\u003cp>\u003cstrong>【举出更贴近实际的例子】\u003c/strong>\u003c/p>\u003cp>说一个我自己的经历，因为我爱人老家离的比较近，我们经常回去，每次回去，我婆婆就会给我们准备很多的东西，不管我们到底喜不喜欢吃，也不管能不能吃完，结果每次带来的东西来不及吃完就扔掉了，我觉得很可惜。所以我跟我爱人很严肃的商量了一下，我们说好了：如果我婆婆给我们带吃的，那么我爱人首先表示拒绝，如果我婆婆开始准备东西了，那么我爱人就在旁边看着准备的都是什么，其中有不爱吃的，就把这个东西拿出去，如果拿出去之后还剩下很多东西，那么在拎上车的时候，就多余的分量在捡出去。现在用这个方法我们就预防可能发生的一切的情况，带回来的东西基本上能够吃掉不会扔了。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>我们一定要这么做吗？仔细想想，如果在每件事情开始之前都能预想到，实现目标的过程中可能会出现的问题，我们就会有更多的成功机会，而不会在困难出现的时候措手不及甚至放弃目标。\u003c/p>\u003cp>举个例子，小新下班之后，告诉她爱人自己要晚一点回去，并希望爱人能够做好饭，结果对方对做饭这件事情非常的反对，直接就回复我不想做饭，因为小新没有料到对方会拒绝，所以悻悻的挂了电话。如果她在打电话之前能够预想一下对方的反应，并提前做好预案和说辞，成功的几率就会大增。\u003c/p>\u003cp>\u003cstrong>【可能出现的异议】\u003c/strong>\u003c/p>\u003cp>还有小伙伴会问，“如果...那么..”的情况经常发生，从小我们就用这个学习造句，这根本算不上是什么方法，最直接的，我们常说“如果他不同意，那么我们就不做了”。\u003c/p>\u003cp>在这里我需要去提醒大家的是，“如果...那么...”这个方法是为你前面设置的目标而服务的，最终的目的是为了帮助目标的达成。而在现实生活中大家常说的“如果...那么...”已经改换了目标。\u003c/p>\u003cp>我们举个例子，比如今天中午你的目标是吃一碗油泼面，按照片段中“如果...那么...”的方法应该说：“如果A饭馆没有油泼面，那么我就去B饭馆吃”，而实际生活中我们说的是：“如果没有油泼面，那我就吃炒米饭”，我们会发现目标已经改变了\u003cbr>\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003cp>学习了“心理对照”以及“心理对照”的应用，下面我们来做一个案例研讨。小北的公司最近受到大环境的影响，经营状况不太好，公司在传闻他的岗位可能会被辞退，虽然被辞退有补偿金，但小北并不想离开公司，不过为了以防万一，小北还是在招聘网站上登出了简历，如果你是小北，想一想此刻你的目标是什么，你有哪些困难，如何应用“如果...那么...”的方法来帮助他实现目标？\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>小北的目标是不能没有工作，在这里他还有一个目标是想留在原公司。\u003c/p>\u003cp>他的困难是：岗位可能被裁掉，而没有找到合适的工作。\u003c/p>\u003cp>解决方法：因为现在公司只是在传言岗位会被裁，所以方法是这样子：如果小北的公司不裁他的岗位，小北就安心上班，如果岗位被裁掉，那么小北可以考虑转岗，如果原公司没有岗位可转，那么小北就找新工作。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>非常感谢小伙伴的分享，我想这样小北应该就可以放松了。\u003c/p>\u003cp>接下来请大家想一想自己在未来的一周或者是一个月之内，会不会遇到这样的场景：\u003c/p>\u003cp>在你和家人的沟通过程中，家人可能会否定你的想法；\u003c/p>\u003cp>在工作中，可能会有同事拒绝你的请求；\u003c/p>\u003cp>或者是当你在和朋友一起的时候，朋友会不同意你的决定；\u003c/p>\u003cp>你会遇到什么样的场景呢？在这个过程中你的目标可能是什么？会出现哪些障碍？请你用“如果...那么...”的方法解决问题。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>我想去参加赵周老师1月份在郑州的课程，但是我爱人可能会不同意，因为最近最近花钱太多了。如果他不同意我的想法，那么我就要极力说服他：虽然我最近花钱是比较多，但是我学会了这个课程之后，在19年我会把它化成线下的课程，就可以收费了，到时候钱就回来了。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>非常感谢小伙伴的分享，希望这个方法可以帮助到大家。也非常感谢大家的积极参与。\u003c/p>\u003cp>今天我们首先学习了通过进行大脑的过滤机制的设置这个方法，使我们顺利获得了自己想要的结果。然后我们学习的是通过“心理对照”的学习，促使我们在积极心态的同时去预想困难是什么，再用“如果..那么..”的方法来克服，这样面对困难，我们就会有更多的准备，从而更顺利的实现自己的目标。\u003c/p>\u003cp>相信这些方法一定可以在实际生活中帮助到我们，促使我们升职加薪，当上总经理出任CEO，迎娶白富美，走上人生巅峰。\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1543805478000,"updated_at":1543805478000,"ria":true},{"id":6620,"topic":" 如何拒绝他人","learn_goal":"成功过级TF3-1","remark":"一本职场人士的床头书。拒绝他人很难么？好的，现在四步就能帮你提高成功拒绝他人的几率。","level":"TF3-1","duration":60,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"【开场介绍】各位伙伴大家好，我是石家庄梧桐分舵的拆书家Mona，非常高兴今天能和大家一起学习新的知识，共同成长。\r\n【学习目标】希望大家在学习了今天的内容之后，可以使用“积极拒绝”的方法，帮助自己改善日常生活中不能成功拒绝他人的情况。\r\n【事件场景】请大家跟我一起想象这样一个场景，最近你的工作特别忙，各种总结、报告、PPT，你感觉自己这周末都休息不了了，这时办公室里另一个伙伴走过来，递给你一沓资料，对你说：亲爱的，这个报告非常着急，我手下的人弄不了，给你两天的时间，周四给我成品。你思考了一下，非常真诚的看着他，说：对不起，亲，我手头有一大堆工作，这个报告我真的没有时间弄了。你发现对方很勉强的看着你，显然他不高兴了，最后，他悻悻的撇撇嘴就走了。\r\n【提问】不知道你平时是如何拒绝他人的呢？直接说NO么？对于自己的拒绝他人的方式，你感到满意吗？你有没有想过更好的拒绝他人的方法呢？\r\n【影响】我们发现，在很多情况下自己没有办法不拒绝他人，因为如果对他人说‘Yse’，那么我们只能对自己的事情说‘No’。但在拒绝的过程中，很有可能发生不愉快，小的拒绝可能只是当场比较尴尬，而某些事情的拒绝，就可能会使你失去一个伙伴，甚至一份工作。\r\n【解决】给予他人帮助，当然是一种美德，但总会有拒绝他人的时刻，那么如何用他人能够接受的、理解的方式来拒绝他人呢？今天分享的这个片段就会告诉我们，在面临他人的要求时，可以通过四个简单的步骤，提升成功拒绝他人的方式。\r\n今天的内容来自于《七堂思维成长课》，这是一本非常好的职业人士的床头书，它可以帮助我们聚焦工作目标，提高执行力，扩大影响，发现自己的优势。\r\n【过度】接下来我们来分一下组啊，今天人不多，我们就是一组，\r\n下面呢，请大家花两分钟的时间来阅读一下原文，看完的伙伴请示意我。","ratings_count":1,"texts":[{"id":9955,"quote":"\u003cp>什么是积极的拒绝\u003c/p>\u003cp>现在想想，我们一般是如何优雅地拒绝一个请求的。我们首先说“真的很抱歉，我没办法出席会议/接手项目/完成你交代的画自两像这件事..听起来很礼貌，但若以发出消极信号的“真的很抱歉”开头，哪怕你满腔好意，还是会让对方高度戒备。他们的大脑马上就进人了防守模式:“你要退出!出现威胁!”在这种模式下，不像处于最佳状态时那样，人们没有精力来大方豁达地思考问题。你可能还在期待对方能理解和支持你要处理的要紧事，但人们一旦处于防守模式，你就很难获得理解。\u003c/p>\u003cp>安东尼讲了他最近一个例子，他用积极的拒绝做好了工作安排，他工作中特别耗时间的一项任务是远途出差，他经常答应出差去半有意思，但并不要紧的事，最近她答应了去吉隆坡出差，后来才意识到要腾出时间出差有多困难。他觉得没办法推掉出差计划，但去出差情形更槽，那意味着他只能马马虎虎完成项目工作，但项目对公司的未来至关重要。最终，他意识到自己不得不通知组织者推掉出差这样才能在日程上腾出足够的时间。\u003c/p>\u003cp>正常情况下安东尼可能会这么写:\u003c/p>\u003cp>“非常抱歉，很不巧我没办法和你一起出差去吉隆坡了。我们最近接了三个大项目，我发现项目工作太多，忙得人不可开交。所以尽管我多方努力，实在腾不出时间出差。再次深表歉意。”\u003c/p>\u003cp>与之相对，安东尼做出的积极的拒绝如下:\u003c/p>\u003cp>“非常荣幸收到你的邀请去吉隆坡。你手头的工作真是既了不起又吸引人。如你所知，我们这边的业务最近几个月也增长迅猛。我们接下来三个让人振奋的新项目，能真正让客户改变对营销的看法。我未来几个月都会忙于搭建这些项目，不负众望取得项目成功是我的职责所在。但是，为了全力工作，我不得不放弃很多事情，很遗憾，其中一件就是不能和你共赴吉隆坡。我此前非常期待这次出行，所以现在也很失落。如果我能帮忙联系到取代我的人，为出差团队贡献价值，请告知-我心里也有些人选。 与此同时，祝你旅行一切顺利， 取得丰硕成果。”\u003c/p>","explains":"\u003cp>\u003cp>【原文讲解】\u003c/p>\u003cp>接下来我们一起来回顾一下这个片段的内容。\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>：这个片段告诉我们什么是&quot;积极拒绝&quot;，其实理解起来并不难，&quot;积极拒绝&quot;就是用对方能够接受的方式拒绝他人。这种方式不会让对方对我们产生消极的情绪，也不会因为拒绝而对我们产生敌意。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>：在拒绝他人的时候，我们常常简单的告诉他人“不”，比如我们会说“对不起，我没时间”或者说“我觉得不行”，当然这是最高效的方式，但是却不利于我们与他人关系融洽。其实我们已经很礼貌的对他人表示歉意，说明拒绝的理由，也觉得自己已经很真诚了，但是“不能”“不行”“没时间”，这种带有否定意味的词语是消极的，它表示你对此事丝毫不感兴趣，你不认可对方的行为，这件事情也不被你接受，所以不管你的理由是多么的充足，让对方理解你也是难上加难。\u003c/p>\u003cp>\u003cstrong>【例辨析概念】\u003c/strong>\u003cstrong>我们来举两个例子来理解一下什么是积极的拒绝，什么是消极的拒绝。\u003c/strong>\u003c/p>\u003cp>小新拒绝小丸子一起去看电影的要求，说道“真对不起，我今天作业很多，没有时间陪你一起去看电影，要回家写作业了”。很显然，小新在一开始就说出了“不”，它表达的是一种消极的信息，这就是消息的拒绝。\u003c/p>\u003cp>海绵宝宝不能帮派大星去买饭，最后海绵宝宝说：我还是没有办法帮你，你自己解决吧，再见。”这也不是积极的拒绝，因为在最后他没有温情的结尾，让人感觉到很失望。充满了消极的味道。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>那么我们到底怎么做才是用“积极拒绝”的方式拒绝他人呢？\u003c/p>\u003cp>\u003cstrong>首先我们应该热情的开场，认可并且赞美对方的请求。\u003c/strong>\u003c/p>\u003cp>以积极而不是消极的信号开头，可以提高成功拒绝的概率。\u003c/p>\u003cp>\u003cstrong>第二步说明你正在做的事情。\u003c/strong>\u003c/p>\u003cp>当然请不要以真的很抱歉开场，你可以轻松的、明确的向对方说出你正在积极准备的要紧事，解释一下这件事情的重要性、重大意义，或者是有趣的原因，最好这个理由也是对方认同的。\u003c/p>\u003cp>\u003cstrong>第三步表达你的拒绝。\u003c/strong>\u003c/p>\u003cp>在说明情况之后表达你的遗憾之情，也就是告诉他你无法答应他的请求。\u003c/p>\u003cp>\u003cstrong>最后是温情的结尾。\u003c/strong>\u003c/p>\u003cp>温情体现在表达你的关心，例如你可以在回复他们的时候说“我没有时间，但我能向你推荐一个能办这个事情的人”，或者是说“我希望我能帮到你，不如我们试试......样的方法&quot;，此时你的关心，你希望能帮助到对方的心情，会让对方感觉到你的真诚，促使对方更理解你。最不行我们还可以热情的祝福对方顺利完成任务，取得成功。这种祝福是很重要的结束语，因为我们平时总是在忙着表达自己的歉意，而忘记了表达对成功的祝福。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>就是通过这么简单的四步，可以帮助我们提高成功拒绝他人的几率，那么大家来试想一下，这其中哪一部最难，你最容易忽略的是哪一部呢？\u003c/p>\u003cp>\u003cstrong>【学习者反馈】\u003c/strong>热情的开场，并且赞美对方的请求是比较难的，因为自己很难在当下就转换角色，意识到我们要热情，而且还能赞美对方的请求。\u003c/p>\u003cp>\u003cstrong>【强调不这么做的坏处】\u003c/strong>有小伙伴说一定要这么拒绝他人吗？当然你可以不用积极解决的方法。但是很显然，如果你常常直接对他人说“不”，就会让对方觉得你可能不擅长团队合作，下次在你需要帮助的时候，可能就找不到愿意伸出援助之手的人。我们在生活中也不喜欢这样的人，当你问他们一个问题，他们总会第一时间给你否定的答案，这种人通常会被看作是消极的人，而积极的拒绝方法则没有这些后患。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>在生活、工作中，基本上你想拒绝的事情，差不多都可以适用于积极拒绝的方法。但需要注意的是，并不是使用了这种拒绝的方法，你就一定能够成功的拒绝他人，我们知道这种方法是帮助提高成功拒绝的几率。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>\u003cstrong>【催化学习者应用】\u003c/strong>那现在我们已经学习完了积极拒绝的方法，接下来我们尝试写一个小剧本，对这个方法进行应用。\u003c/p>\u003cp>请问大家听说过日本的动漫人物柯南吗？\u003c/p>\u003cp>【学习者】听说过。\u003c/p>\u003cp>我们今天的人物就是柯南和毛利叔叔。\u003c/p>\u003cp>时间是小兰高中毕业的当天。\u003c/p>\u003cp>地点是在通往案发现场的路上。\u003c/p>\u003cp>起因是柯南和毛利叔叔正在调查一起谋杀案，柯南突然得知小兰在毕业典礼上会被表白，而小兰很有可能接受对方的表白，于是柯南准备去找小兰。\u003c/p>\u003cp>经过是柯南告诉毛利叔叔自己要去找小兰，而毛利叔叔担心自己无法破解凶杀案，找不到凶手，不让柯南离开。\u003c/p>\u003cp>结果是柯南拒绝了毛利叔叔。\u003c/p>\u003cp>接下来请大家编写剧本，注意应用积极拒绝的方法让柯南拒绝毛利叔叔。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>我们的剧本：人物就是柯南和毛利叔叔，地点是在通往案发现场的路上，时间是小兰高中毕业的当天，起因是柯南不能去案发现场了，而是要去阻止小兰被表白这件事情，不过毛利叔叔不同意。结果就是小楠柯南拒绝了毛利叔叔的要求。\u003c/p>\u003cp>下面是对话：\u003c/p>\u003cp>柯&nbsp; &nbsp; &nbsp; 南：毛利叔叔，我要离开。\u003c/p>\u003cp>毛利叔叔：天哪，现在你要离开？不可以，马上就要到案发现场了。你非常的重要。\u003c/p>\u003cp>柯&nbsp; &nbsp; &nbsp; 南：可我不能够再耽误下去了，我的女朋友要被别人抢走了。\u003c/p>\u003cp>毛利叔叔：但是如果你离开了，我怕我自己没有办法搞定这个案件。\u003c/p>\u003cp>柯&nbsp; &nbsp; &nbsp; 南：毛利叔叔，你知道的，我对破解案件这种事情是非常感兴趣的，而且他真的能够显示出我的聪明才智，我们合作的也非常的愉快，这是一件令我非常兴奋的事情（第一步）。毛利叔叔，你也一定有过美好的爱情，你知道，我的女朋友对我是多么重要，现在她要被别人抢走了，我相信你也一定不想看到我失恋的样子，而且失恋之后，我会很不在状态，我不想这样子（第二步）。所以我不能陪你去案发现场了，我要去挽救我的爱情（第三步）。其实现在的你早已身经百战，你处理过更多比这个案件更加复杂的谋杀案，所以你肯定能够破解它。目暮警官已经到达案发现场了，相信在他的帮助下，以你非常丰富的经验一定可以破解这起案件。我只要把这个事情搞定，马上就回来（第四步）。\u003c/p>\u003cp>毛利叔叔：嗯，好吧，那你早去早回。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>非常感谢大家的分享。今天通过四个步骤的学习，大家对积极拒绝的方法有了认知和了解，并且也掌握了积极拒绝的步骤，希望大家在日常生活中可以去应用它，最终来改善自己在日常生活中不能成功拒绝他人的苦恼问题。\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543676999000,"updated_at":1543676999000,"ria":true},{"id":6419,"topic":"《七堂思维成长课》TF2-4","learn_goal":"完整的阐释片段内容，顺利通过2-4","remark":"关于人类是如何思考，感觉，做决定，是如何表达，行动的，人们已经进行过大量的探索，并一步步获得了重大发现。然而，这些发现还有很多原封不动地待在学者的论文里，其中蕴含的关于人类行为的见解却非常值得人们学习并实践。韦伯就充当了转化者的角色，作为一名资深的咨询师，她将“行为学 + 心理学 + 脑科学”转化成好用的自我调适技术，教人们融入一天的生活中，获得美好的一天。","level":"TF2-4","duration":120,"status":29,"type":0,"chaishujia":{"username":"王晓霞","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"各位伙伴，大家好，我是石家庄梧桐分舵的拆书家Mona。非常的高兴今天能和大家一起分这本享《七堂思维成长课》。\r\n【图书介绍】\r\n【F】今天我分享的内容片段来自《七堂思维成长课》，它的作者是来自英国的卡洛琳.韦布。卡洛琳在全球知名的管理咨询公司——麦肯锡工作，大家都知道在麦肯锡，女顾问不易，干到女合伙人更是难上之难。而卡洛琳完全是灭绝师太类型的存在，她在麦肯锡供职12年，是全球1%的女性资深合伙人。在本书中，她深度剖析了她所接触到的精英人群是如何安排自己的生活，如何面对负面情绪，以及如何结交和管理人脉的，并教给我们打造属于自己的高质量生活的方法。\r\n【A】因为作者有过非常全面的麦肯锡训练的经历，而且她也在麦肯锡训练了无数的新人，所以她积累了大量精英人群的实际问题和解决方案。并且她深入研究了行为科学，心理学，和神经科科学，研读了600多篇的论文和专注，所有的精华凝结在此书当中。\r\n【B】在书里，作者进行了详细的理论讲解，每一部分提到的方法和建议都可以直接拿过来用，对实际工作的帮助性很大，尤其是对于职场人士非常适用，实用。\r\n【学习目标】希望大家学习完这个片段之后呢，可以帮助你在每天或者是每件事情开始之前，使用为大脑建立过滤机制的方法，让每天或者是每件事情发展的更加如你所愿。","ratings_count":1,"texts":[{"id":9725,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>分组: 畔月姐跟志博一组，丽欣姐姐跟小曼姐是一组。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>接下来就请大家花两分钟的时间读一下 原文，看完的请示意我。\u003c/p>\u003cp>【R】\u003c/p>\u003cp>我们无法掌控一切，但我们能够做到的是调整工作时间的感受，更用心地设置感知过滤机制。这时候每天坚持设定意图就很有用了，养成这个习惯能让我们留意自己每天的优先事项、关注的事和情绪。\u003c/p>\u003cp>我的办法如下，花一小段时间从三个角度来考虑(这三个角度的英文单词都以字母A开头，方便记忆) :\u003c/p>\u003cp>目标(Aim):想想今天活动中最重要的事项、要见的人，以及要做的工作。要办成这些事最重要的是什么?那就是你的真实目标。\u003c/p>\u003cp>态度( Attitude):下个工作日要来了，花时间留意并且正视那些支配你思维或情绪的你所关心的事。这些你所关心的事能帮你达成真实目标吗?如果不能，你能暂时把它们放在一边吗?\u003c/p>\u003cp>关注( Attention):从你实际的优先事项出发，你想把精力集中在哪儿?想清楚你想更多看到什么，然后确保自己按计划寻找。\u003c/p>\u003cp>我共事过的大部分人都认为，最好是在一天开 始前就弄清楚这些问题，可以是在早上或者前一天晚上。但因为这个日常习惯占用的时间不会超过一两分钟， 你从一个任务飞奔到下一一个任务之前再找时间设定意图也不晚。\u003c/p>","explains":"\u003cp>【I讲解】\u003c/p>\u003cp>\u003cstrong>WHAT\u003c/strong>\u003cstrong>：这个片段讲解的是在开始做一件事情，或者在一天开始的时候，人类建立好大脑的过滤机制的办法。\u003c/strong>在这里我要解释一下什么是大脑的过滤机制。大脑对于外部复杂的世界只能分配很有限的注意力，在一件事情发生的过程中，大脑就会优先处理它自认为重要的事情，同时把不太重要的事情过滤掉。比如当你集中精力看短信的时候，大脑就会认为没有必要分配注意力去理解你同事说的话，当同事提高的声音通过耳朵最终到达你的大脑里时，你会突然惊醒，反问道“啊，你刚才说话了？”\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>\u003cstrong>：\u003c/strong>也正是因为这种过滤机制，于是我们总是能够看到我们想看到的事情，而忽略掉那些在大脑中没有任何意识的事务。所以如果可以在每天或者每件事情开始之前，就在自己的大脑中植入\u003cstrong>优先事项\u003c/strong>，植入那些你更倾向于发生的事情，大脑就会在真实的世界里仔细的寻找这些你植入的景象，帮助发现生活或者是工作中潜在的可能性。\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003cstrong>：\u003c/strong>那么我们要如何做呢？\u003c/p>\u003cp>\u003cstrong>首先，建立一个提醒自己，大脑是存在这种过滤机制的提示。\u003c/strong>虽然你理解了什么是过滤机制，但是在生活和工作中，并不会总能想起这件事情，它是需要我们有意识的去做的，比如，你想要在拥有美好的一天，那么你可以把每天叫醒自己的闹铃名字改为：美好的一天开始了，或者你想要提醒自己对每件事情都很乐观，那你也可以把它做成图片，作为你的手机背景，用以来提示你。\u003c/p>\u003cp>\u003cstrong>第二，在一天开始之前或者是你进行一项重要的活动之前，想一想你的目标是什么\u003c/strong>。是要完成什么事，见什么人，或者是完成什么样的工作，这就是你要达成的目标。比如今天你要去辅导新来的小A，了解新产品知识，此时领导说让你去做上个项目的汇报，然后你就去做汇报了。你可能就会忘记你要去辅导小A 。如果你你早上对于你今天的目标进行了预想，你就可能在汇报的时候想起小A也参加了这个项目，然后又想起“哦，今天我还有个任务是去辅导小A的新产品知识”\u003c/p>\u003cp>\u003cstrong>第三，感受一下你在做那件事情的时候是什么样的心情？\u003c/strong>你该以什么样的态度去面对这件事情呢？关于态度这一点，你一定要预先想好。因为你这时植入的感觉是导火索，它会引领你在过程中寻找于此相同的感觉。比如你觉得辅导会进展的很顺利，你的状态很好，小A对某些地方不太懂，但是思路是没有问题的，两个人对存在问题的地方做了讨论和确认，小A很认真。那大脑就会寻找顺利的蛛丝马迹，而如果你非常的疲惫，并没有对这个辅导的感受进行预想，过程中，如果遇到小A不懂的地方，她很纠结，或许，你就会感到很麻烦，不明白为什么这么简单的问题她居然不懂，可能在这个过程中你就会感受到不愉快，烦躁。\u003c/p>\u003cp>\u003cstrong>第四，从你期待发生的事情出发，把注意力集中在期待发生的事情上。\u003c/strong>正如哲学家所说的那样，你只会看到你想看到的。如果大脑能够从你的预先设置的积极态度中获取到信息那样，你的关注点就会在于更加积极的地方，比如你在辅导小A的时候，小A对同一个问题很纠结，如果你的关注点是积极的，你可能会认为她很认真，做事仔细，是值得培养的人。但是如果你没有预想过，你的关注点或许就会变成了你的心情，你感到不安，疲惫，这样就会很糟糕。此时请去留意事件中更加值得你去关注的点，而这个点正好与你的态度相应证。\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>在我们的大脑中过一遍“目标-态度-关注点”这三个优先事项只需要很短的时间，但对于我们来说却是至关重要要的，因为如果你不这样做，就会很快忘记自己的目标，从而受到环境的影响，如果是开心的积极的事情还好，一旦你产生了消极的想法，大脑的过滤机制就会把关注点放到消极的事情上面，从而你就面临这“看什么都不顺眼”的状态。所以如果你可以建立一个积极的过滤记住，就会避免“因为心情不好，整个世界都黑暗了”的状态。\u003c/p>\u003cp>【可能出现的异议处理】\u003c/p>\u003cp>或许有的伙伴会说，这真的管用么？在一件事情开始之前预想一遍“目标-态度-关注点”，事情就会按照好的方向发展么？在这里需要说明的是，事情不是因为人类设定的“目标-态度-关注点”这三个优先事项而改变，而是人类的行为改变的，因为大脑因为预先设定的情形，注意到与优先事项更类似的信息，我们的行为就是受这些信息所左右的。比如我跟你正在沟通关于团队出游的事情，我的优先事项，关注点，和情绪都会形成我对我的过滤机制产生影响，如果我设置的优先事项都是为了顺利完成这个沟通，我在沟通的时候，大脑就会更加善于发现与完成沟通有关的信息，于是沟通也会进展的更加顺利。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>【激活经验1】\u003c/p>\u003cp>现在请大家跟我回忆一下你的工作或者是生活中，有没有发生过这样的事情，你被安排了你要去做某件事情，你一听就觉得：天呐，怎么会给我安排这件事情呢？这件事情怎么能做好呢？然后你去做这件事情，果然就按照你预想的那样子发展的，真的是糟糕透了。有没有发生过这样的事情呢？\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>丽欣姐姐分享：有一次我老板让我跟他汇报工作，我当时没有准备，所以一听到这个消息就很懵，心理觉得压力很大，怕自己表现的不太好，结果那次汇报真的就很尴尬。\u003c/p>\u003cp>【A2引导】\u003c/p>\u003cp>恩，看来大家真的都有过这样的经历，而且那件事情也给各位留下了很深刻的印象，那么我们现在思考一下，现在你已经学会了建立大脑的过滤机制的方法，\u003cstrong>先给自己一个提示，让自己意识到你要建立一个过滤机制，接下来，分别对三个优先事项：目标，态度和关注点进行一下设置，分别植入信息，\u003c/strong>你设想一下，在近期的未来是不是还有类似的事情发生呢？那么到时候\u003cstrong>你要怎么提示自己给大脑建立过滤机制的，如何植入信息，那这个事情又会变成什么样子呢？\u003c/strong>大家讨论一下，我们一会儿找伙伴在分享一下。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>丽欣姐姐：类似的事情：下周我再去做一个产品汇报，那在那之前，我想应该会把那天的闹铃改为：“ 成功的产品汇报”来提示自己，我的汇报会很顺利，很成功。我给自己定下的目标是完美的呈现我的产品PPT，我的态度会是非常平和的，感到自信的，能够看到台下大家赞许的目光，我感到很满足，我会把我的关注点放在产品的细节上，而且我会关注到台下人们给我的鼓励。我觉得这样的话， 我的状态真的很不一样了，一定会很顺利。\u003c/p>\u003cp>【过渡】恩，非常感谢丽欣姐姐的分享。这就是在自己的大脑里建立了过滤机制给我们带来的好处，我们会调动自己一切的能力促使事情发展的更加顺利。\u003c/p>\u003cp>那在这个过程中，我们还可以做什么可以促使这个过程更加顺利呢？刚才丽欣姐姐说：她给自己定下的目标是完美的呈现产品PPT，那在设立目标的时候，我们是不是也有需要注意的点呢？接下来我们来看一下第二个片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":9727,"quote":"\u003cp>【R】\u003c/p>\u003cp>不可思议的是，加强积极意图的一个很好的办法居然是稍微思考一下消极面。我指的是诚实的思考哪些因素可能阻碍你实现目标，然后你就能直面这些障碍。这个技巧被称为“心理对照”，顾名思义，就是将理想结果与烦人的日常生活进行对比。\u003c/p>\u003cp>这让人联想到商业书籍《从优秀到卓越》中提到的“斯托克代尔悖论”。这个悖论的名称取自美国海军中将詹姆斯斯托克代尔采用双面应对策略，它作为越南战俘熬过了八年艰难的岁月幸存下来，其间他身边的人，大多在绝望中走向灭亡，是德国戴尔认为不止悲观主义者，缺乏忍耐艰难处境的心理力量，盲目的乐观主义者也缺乏，因为他们要面对积极的信念落空后连绵不断的失望情绪，斯托克代尔这么说：“无论面对的是何种现实，你绝对不能把你终将获胜的信念——这点你绝对不能丢”\u003c/p>\u003cp>如今心理学家已经确认，这种现实的理想主义，只是确保我们将意图转变成行动的入场券，感谢上天，我们不用面对丈夫为存活下去，必须面临的那些恶劣挑战，但每天我们也会面对各种障碍，比如不成熟的技术手段，同时最后一分钟意想不到的请求等等。研究发现，人们如果在细心思考其想要的结果的同时，也仔细思索面临的障碍，并且做两手准备，那么他们达成目标的概率就会大增。研究发现，我们生活的很多方面都是如此，不论是职场事业，学业成绩还是恋爱关系。\u003c/p>\u003cp>为了每天在制定计划时通过心理对照获益，你可以问自己：\u003c/p>\u003cp>Ø&nbsp; 在你成功达成今天目标的路上，什么最可能成为障碍？\u003c/p>\u003cp>&nbsp; Ø为防止出现障碍你的“如果…..那么”临时计划是什么？\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>在学习完这个片段之后，在你每次设立目标的时候，你都能预想到实现过程中的问题，并且把问题写下来，并用“如果…..那么….”寻找到解决方法。\u003c/p>\u003cp>【I讲解】\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这一段文字告诉我们什么是“心理对照”，以及如何应用心理对照产生积极的效果。\u003c/strong>那什么是“心理对照”呢？就是我们在看待问题的时候，不仅要想到积极的方面，也要思考消极的方面，思考可能会遇到什么困难，这样的话，我们可以更快一步的解决这个问题。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>当我们想要建立好一个过滤机制的时候，我们也不能只想好的方面，因为在事情发生的过程中，不会有魔法发生，促使现实情况完全按照我们的意图来，那么在我们设立目标的时候，不妨思考一下消极的地方，这样可以预防突发事件，提前对于突然情况的反应时间，不会让自己措手不及。\u003c/p>\u003cp>【细化步骤】\u003cstrong>HOW:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一，仔细思考你的目标，把它写下来。当你的目标很重要的时候，请把你的目标写下来，这对于你正视这个目标很有帮助。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二，思考一下，在达成目标的过程中，会有什么障碍\u003c/strong>。为了完成目标，我们需要非常细致的理清我们在这个过程中要做什么，并且知道我们什么时候去做，所以如果你思考清楚在这个过程中有哪些困难存在，将会在什么时候发生，那么我们就能提前反应，做好应对困难的准备。\u003c/p>\u003cp>\u003cstrong>第三：思考一下，如果出现这些障碍，你会有什么方法解决。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四，用“如果…..那么……”的方法，做出计划，以对应障碍。\u003c/strong>关于“如果…那么…”的规则，我们可以这样理解：\u003cstrong>“如果X情况发生了，那么我就会采取Y行动”\u003c/strong>。这一步骤其实是在给我们想象的未来和采取行动的现实之间搭了一座桥，让我们可以更好的把控事情的走向。比如我跟小H在沟通团队出游的事情，我的目标是让小H同意现在的出游方案，关于具体的出游地点，很多同事建议选择宁波，我知道小H可能会不同意，因为经费不够，那么我会思考：如果在沟通的过程中，小H对出游地点有异议，那么我就会拿出旅行社给的报价，告诉小H，其实现在这个季节去宁波比去近的地方也多花不了多少钱，或者说，如果在沟通过程中，小H对出游地点有意义，那么我会提议用投票的方式解决，让同行的同事们选择去哪里。这都是“如果…..那么….”的应用。\u003c/p>\u003cp>【举出更贴近实际的例子】\u003c/p>\u003cp>我说一个我自己的经历，因为我爱人老家离市里很近，我们经常回去，每次回去呢，我婆婆就会给我们准备很多东西，比如一些青菜啊，水果啊，有时候还给我们带干粮，不管是我们喜欢吃的，还是不喜欢吃的，结果是每次带过来很多，但是我们吃不了，很多都坏了，扔了，我觉得很可惜。所以，最近几次回去，我都给自己定好目标，就是：不带那么多东西回来。我跟我爱人也很严肃的说了这个问题，我们说好了，如果我婆婆说要给我们带吃的，那么，我爱人首先表示拒绝，如果我婆婆开始准备了东西了，那么我爱人就在旁边看着都是准备的什么东西， 如果其中有我们不爱吃的，那么我爱人就要说，这么个东西我们都不爱吃，直接拿出去，如果拿出去之后还是有很多东西，那么我就看着把多余的，我们可能吃不了的分量捡出去。现在看来这个方法，还是很好用的，就是我们真的预防到了可能发生的一切情况。现在在带东西回来，基本不会扔掉了。\u003c/p>\u003cp>【强调不这样做的坏处】\u003c/p>\u003cp>那我们一定要这么做么？仔细想想，如果我们在做每件事情之前都能料想一下在实现目标的过程中， 可能就会出现的其他问题，这样我们就可以有更多的机会完成目标，而不是因为措手不及而放弃目标。举个例子，小书下班之后给爱人打电话，告诉他自己可能要晚一点回去，并且希望爱人能早点回去做饭。结果对方对她晚回家的事情没意见，但是对做饭这件事情却很反对，直接就说我不想回去做饭，因为小书没有料想到对方会拒绝，所以悻悻的挂了电话，但是如果她在之前猜测到对方可能会有其他的想法，那么她就能提前准备好手说词，对方拒绝的几率就会很小了。\u003c/p>\u003cp>【可能出现的异议处理】\u003c/p>\u003cp>可能有伙伴会问，“如果…那么…”的情况经常发生，这个根本算不上什么方法，最直接的，我们常说“如果他不同意，那么我们不做了”，在这里我想提醒大家的是，“如果….那么….”是为前面的目标而服务的，最终的目的是为了帮助目标达成。而现实中大家常说的“如果….那么….”已经换了目标。我们举个例子，今天中午你的目标是想吃一碗油泼面，如果按照本片段的“如果…那么…”方法来说，就是如果A饭馆没有油泼面，那么我就去B饭馆吃。而不是如果没有油泼面，那么我就吃炒米饭。我们会发现，目标已经变了。\u003cbr>\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>学习了“心里对照”以及“心里对照”的应用，我们来做一个案例研讨。你的朋友红红，有一个特别爱为她操心的母亲，两个人总是在红红的生活问题上发生意见的相左。红红特别想跟母亲好好的，较为顺利的，不发生冲突的谈一次，告诉母亲自己有自己的生活方式和计划，让她不要太操心，现在请你利用刚才学到的方法，讨论一下，红红的目标是什么，可能出现的困难是什么，红红应该如何应用“如果….那么…..”这个方法呢？&nbsp; 请帮助一下红红。\u003c/p>\u003cp>【小组讨论后的分享】\u003c/p>\u003cp>志博：红红的目标：自己做主自己的生活。阻碍是妈妈把太多的关注点太集中在自己的身上。给红红的方法：如果妈妈总是想左右自己的生活，那么红红就给妈妈培养一个兴趣爱好，把妈妈的注意力吸引过去，如果妈妈没有爱好，那么红红就跟妈妈好好的谈一次，告诉妈妈自己已经成人，没有自己的生活。如果妈妈还是很执意干涉自己生活，那么她就坚持自己的生活方式，用行动告诉妈妈自己的生活原则。如果妈妈仍然干涉，那么红红可能会跟搬出家里，自己单独居住，在固定的时间回家看望妈妈。\u003c/p>\u003cp>【A2的催化应用】\u003c/p>\u003cp>好，感谢大家给红红的建议。\u003c/p>\u003cp>接下来请大家想一想自己在未来的一周或者是一个月之内，会不会发生类似于下面的事情：比如你要跟老板申请给自己的小组购置电脑，在过程中老板可能因为费用紧张拒绝你，那么你会把自己小组在这个项目上的收益给老板看看， 说明自己可以先垫付然后用后期项目收益补给自己，或者你的朋友希望你陪她过周末，而你的考试临近，不能陪伴，如果她私自决定来找你，那么你会带她一起去图书馆，两个人一起在图书馆度过周末，类似于这两种情形，就是你可能会在未来有个事情要去做，然后在这个过程中，可能会出现什么障碍，需要你去用到“如果….那么…”这个方法？大家有这样的事情么？\u003c/p>\u003cp>【学习者参与】\u003c/p>\u003cp>小曼姐：有，我最近要去筹办年会，这其中就会遇到很多问题，都可以用到这个方法\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>恩。是的，其实这个方法真的是非常的实用，经常可以被用到，希望这个方法可以帮助到你。非常感谢大家的积极参与。今天我们首先学习了在我们开始一天的工作或者一件事情之前，通过对三个优先事项“目标-态度-关注点”进行思考，要给自己的大脑建立一个过滤机制，从而使我们更顺利获得想要的结果，第二个片段则是通过对“心里对照”的学习，促使我们在有积极心态的同时，要去预想困难是什么，再用“如果….那么….”来克服，这样面对困哪，我们会更有准备，从而更顺利的实现自己的目标。相信如果能应用到实际生活中，一定能帮助我们\u003ca href=\"https://www.baidu.com/s?wd=%E5%8D%87%E8%81%8C%E5%8A%A0%E8%96%AA&tn=SE_PcZhidaonwhc_ngpagmjz&rsv_dl=gh_pc_zhidao\">升职加薪、当上总经理、出任CEO、迎娶白富美、走上人生巅峰。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1541732147000,"updated_at":1541732147000,"ria":true}]};